    description public.citext CHECK (char_length(description) <= 300),
    fundtype public.citext CHECK (char_length(fundtype) <= 120),
    accountpiemail public.citext CHECK (char_length(accountpiemail) <= 200),
    fundmanageremail public.citext CHECK (char_length(fundmanageremail) <= 200),
