    legacyreference public.citext CHECK (char_length(legacyreference) <= 40),
    requestedbynetid public.citext CHECK (char_length(requestedbynetid) <= 64),
    requestedbyuserid integer,
    surveycode public.citext CHECK (char_length(surveycode) <= 20),
    staffrequesting public.citext CHECK (char_length(staffrequesting) <= 160),
    staffrequestingnetid public.citext CHECK (char_length(staffrequestingnetid) <= 64),
    purchasereqdate public.citext CHECK (char_length(purchasereqdate) <= 40),
    purchasetype public.citext CHECK (char_length(purchasetype) <= 80),
    destination public.citext CHECK (char_length(destination) <= 200),
    deliverbldgnumber public.citext CHECK (char_length(deliverbldgnumber) <= 20),
    deliverroomid public.citext CHECK (char_length(deliverroomid) <= 40),
    deliverroomcode public.citext CHECK (char_length(deliverroomcode) <= 40),
    businessjustification public.citext,
    additionalnotes public.citext,
    vendorname public.citext CHECK (char_length(vendorname) <= 200),
    vendorweb public.citext CHECK (char_length(vendorweb) <= 300),
    vendoraddress1 public.citext CHECK (char_length(vendoraddress1) <= 200),
    vendoraddress2 public.citext CHECK (char_length(vendoraddress2) <= 200),
    vendorcity public.citext CHECK (char_length(vendorcity) <= 120),
    vendorstate public.citext CHECK (char_length(vendorstate) <= 20),
    vendorzip public.citext CHECK (char_length(vendorzip) <= 20),
    vendorphone public.citext CHECK (char_length(vendorphone) <= 60),
    vendornotes public.citext CHECK (char_length(vendornotes) <= 400),
    splitmethod public.citext NOT NULL DEFAULT 'dollar' CHECK (char_length(splitmethod) <= 10),
    totalcost numeric(12,2),
    status public.citext NOT NULL DEFAULT 'submitted' CHECK (char_length(status) <= 40),
    decisionnote public.citext,
    orderreference public.citext CHECK (char_length(orderreference) <= 80),
    orderedat timestamp(6),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    updatedat timestamp(6),
    closedat timestamp(6),
    hasequipment smallint NOT NULL DEFAULT 0,
    PRIMARY KEY (purchaserequestid),
    UNIQUE (ticketnumber)
);
CREATE INDEX rq_purchaserequests_ix_purchaserequests_status ON purchasing.rq_purchaserequests (status, surveycode);
CREATE TABLE purchasing.rq_purchaseevents (
    purchaseeventid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    purchaserequestid integer NOT NULL,
    purchasefundingid integer,
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 40),
    detail public.citext CHECK (char_length(detail) <= 600),
    bynetid public.citext CHECK (char_length(bynetid) <= 64),
    byname public.citext CHECK (char_length(byname) <= 160),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (purchaseeventid)
);
CREATE INDEX rq_purchaseevents_ix_purchaseevents_request ON purchasing.rq_purchaseevents (purchaserequestid, purchaseeventid);
CREATE TABLE purchasing.rq_purchasefunding (
    purchasefundingid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    purchaserequestid integer NOT NULL,
