    cfopcode public.citext CHECK (char_length(cfopcode) <= 40),
    activitycode public.citext CHECK (char_length(activitycode) <= 40),
    accountdescription public.citext CHECK (char_length(accountdescription) <= 300),
    coa public.citext CHECK (char_length(coa) <= 4),
    fundcode public.citext CHECK (char_length(fundcode) <= 20),
    orgcode public.citext CHECK (char_length(orgcode) <= 20),
    programcode public.citext CHECK (char_length(programcode) <= 20),
    surveycode public.citext CHECK (char_length(surveycode) <= 20),
    amountvalue numeric(12,2),
    amountkind public.citext CHECK (char_length(amountkind) <= 10),
    piname public.citext CHECK (char_length(piname) <= 160),
    pinetid public.citext CHECK (char_length(pinetid) <= 64),
    piemail public.citext CHECK (char_length(piemail) <= 200),
    piproxynetid public.citext CHECK (char_length(piproxynetid) <= 64),
    piproxyname public.citext CHECK (char_length(piproxyname) <= 160),
    pistatus public.citext NOT NULL DEFAULT 'pending' CHECK (char_length(pistatus) <= 20),
    pidecidedbynetid public.citext CHECK (char_length(pidecidedbynetid) <= 64),
    pidecidedat timestamp(6),
    picomment public.citext CHECK (char_length(picomment) <= 600),
    fmname public.citext CHECK (char_length(fmname) <= 160),
    fmnetid public.citext CHECK (char_length(fmnetid) <= 64),
    fmemail public.citext CHECK (char_length(fmemail) <= 200),
    fmstatus public.citext NOT NULL DEFAULT 'pending' CHECK (char_length(fmstatus) <= 20),
    fmdecidedbynetid public.citext CHECK (char_length(fmdecidedbynetid) <= 64),
    fmdecidedat timestamp(6),
    fmcomment public.citext CHECK (char_length(fmcomment) <= 600),
