    inventoryid integer,
    propertytag public.citext CHECK (char_length(propertytag) <= 60),
    receivedat timestamp(6),
    isequipment smallint NOT NULL DEFAULT 0,
    expectedfor public.citext CHECK (char_length(expectedfor) <= 160),
