);
CREATE INDEX rq_purchaseitems_ix_purchaseitems_request ON purchasing.rq_purchaseitems (purchaserequestid, itemno);

-- ==== register keys (PRI_FacilitiesKeys) ====
CREATE SCHEMA keys;
CREATE TABLE keys.app_adminaccess (
    adminaccessid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    accessfunction public.citext NOT NULL DEFAULT 'facilities' CHECK (char_length(accessfunction) <= 30),
    note public.citext CHECK (char_length(note) <= 200),
    isactive smallint NOT NULL DEFAULT 1,
    grantedat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    grantedbynetid public.citext CHECK (char_length(grantedbynetid) <= 64),
    PRIMARY KEY (adminaccessid),
    UNIQUE (netid, surveycode, accessfunction),
    CHECK (AccessFunction IN ('director', 'proxy', 'facilities', 'safety', 'fleet', 'equipment', 'inventory', 'it', 'finance', 'deputy', 'executive'))
);
CREATE INDEX app_adminaccess_ix_adminaccess_netid ON keys.app_adminaccess (netid, isactive);
CREATE TABLE keys.app_attachments (
    attachmentid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    userid integer NOT NULL,
    storedname public.citext NOT NULL CHECK (char_length(storedname) <= 120),
    originalname public.citext NOT NULL CHECK (char_length(originalname) <= 260),
    mimetype public.citext NOT NULL CHECK (char_length(mimetype) <= 80),
    sizebytes bigint NOT NULL,
    exiflatitude numeric(9,6),
    exiflongitude numeric(9,6),
    capturedat timestamp(6),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    purpose public.citext NOT NULL DEFAULT 'photo' CHECK (char_length(purpose) <= 20),
    caption public.citext CHECK (char_length(caption) <= 300),
    requesttype public.citext CHECK (char_length(requesttype) <= 20),
    PRIMARY KEY (attachmentid),
    CHECK (Purpose IN ('photo', 'drawing', 'document', 'other'))
);
CREATE INDEX app_attachments_ix_attachments_request ON keys.app_attachments (requestid);
CREATE TABLE keys.app_auditlog (
    auditid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    userid integer,
    action public.citext NOT NULL CHECK (char_length(action) <= 60),
    targettype public.citext CHECK (char_length(targettype) <= 40),
    targetid public.citext CHECK (char_length(targetid) <= 40),
    detail public.citext,
    ipaddress public.citext CHECK (char_length(ipaddress) <= 45),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (auditid)
);
CREATE TABLE keys.app_digestpreferences (
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    frequency public.citext NOT NULL DEFAULT 'weekly' CHECK (char_length(frequency) <= 10),
    sendday integer NOT NULL DEFAULT 1,
    sendhour integer NOT NULL DEFAULT 7,
    includemine smallint NOT NULL DEFAULT 1,
    token public.citext NOT NULL CHECK (char_length(token) <= 64),
    lastsentat timestamp(6),
    lastitemcount integer,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (netid),
    UNIQUE (token),
    CHECK (Frequency IN ('off', 'daily', 'weekly'))
);
CREATE TABLE keys.app_notes (
    noteid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    userid integer NOT NULL,
    body public.citext NOT NULL,
    isinternal smallint NOT NULL DEFAULT 0,
    importbatchid integer,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (noteid)
);
CREATE INDEX app_notes_ix_notes_request ON keys.app_notes (requestid);
CREATE TABLE keys.app_notifications (
    notificationid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer,
    ticketnumber public.citext CHECK (char_length(ticketnumber) <= 24),
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 40),
    recipients public.citext NOT NULL,
    subject public.citext NOT NULL CHECK (char_length(subject) <= 300),
    body public.citext NOT NULL,
    status public.citext NOT NULL DEFAULT 'logged' CHECK (char_length(status) <= 20),
    errortext public.citext CHECK (char_length(errortext) <= 600),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    sentat timestamp(6),
    PRIMARY KEY (notificationid),
    CHECK (Status IN ('logged', 'sent', 'failed'))
);
CREATE INDEX app_notifications_ix_notifications_created ON keys.app_notifications (createdat DESC);
CREATE TABLE keys.app_notifyrules (
    ruleid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 40),
    matchtype public.citext NOT NULL DEFAULT 'always' CHECK (char_length(matchtype) <= 20),
    matchvalue public.citext CHECK (char_length(matchvalue) <= 120),
    email public.citext NOT NULL CHECK (char_length(email) <= 200),
    displayname public.citext CHECK (char_length(displayname) <= 160),
    note public.citext CHECK (char_length(note) <= 300),
    isactive smallint NOT NULL DEFAULT 1,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    createdbynetid public.citext CHECK (char_length(createdbynetid) <= 64),
    PRIMARY KEY (ruleid),
    CHECK (MatchType IN ('always', 'survey', 'work_type', 'owner', 'request_kind', 'severity_min', 'building', 'life_safety', 'specimen_risk'))
);
CREATE INDEX app_notifyrules_ix_notifyrules_event ON keys.app_notifyrules (eventcode, isactive);
CREATE TABLE keys.app_settings (
    settingkey public.citext NOT NULL CHECK (char_length(settingkey) <= 60),
    settingvalue public.citext NOT NULL CHECK (char_length(settingvalue) <= 400),
    valuetype public.citext NOT NULL DEFAULT 'number' CHECK (char_length(valuetype) <= 20),
    label public.citext NOT NULL CHECK (char_length(label) <= 160),
    helptext public.citext CHECK (char_length(helptext) <= 400),
    sortorder integer NOT NULL DEFAULT 0,
    PRIMARY KEY (settingkey)
);
CREATE TABLE keys.app_statushistory (
    historyid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    fromstatus public.citext CHECK (char_length(fromstatus) <= 20),
    tostatus public.citext NOT NULL CHECK (char_length(tostatus) <= 20),
    userid integer,
    comment public.citext CHECK (char_length(comment) <= 600),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (historyid)
);
CREATE INDEX app_statushistory_ix_history_request ON keys.app_statushistory (requestid);
CREATE TABLE keys.app_users (
    userid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    displayname public.citext NOT NULL CHECK (char_length(displayname) <= 160),
    email public.citext NOT NULL CHECK (char_length(email) <= 200),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    unit public.citext CHECK (char_length(unit) <= 120),
    phone public.citext CHECK (char_length(phone) <= 40),
    role public.citext NOT NULL DEFAULT 'staff' CHECK (char_length(role) <= 20),
    isprovisional smallint NOT NULL DEFAULT 0,
    isactive smallint NOT NULL DEFAULT 1,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    lastloginat timestamp(6),
    PRIMARY KEY (userid),
    UNIQUE (netid),
    CHECK (Role IN ('staff', 'coordinator', 'approver', 'admin'))
);
CREATE TABLE keys.gis_keyevents (
    keyeventid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    roomkeyid integer NOT NULL,
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 20),
    keystatefrom public.citext CHECK (char_length(keystatefrom) <= 40),
    keystateto public.citext CHECK (char_length(keystateto) <= 40),
    detail public.citext CHECK (char_length(detail) <= 600),
    bynetid public.citext CHECK (char_length(bynetid) <= 64),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (keyeventid),
    CHECK (EventCode IN ('issued', 'returned', 'lost', 'edited', 'voided'))
);
CREATE INDEX gis_keyevents_ix_giskeyevents ON keys.gis_keyevents (roomkeyid, createdat);
CREATE TABLE keys.gis_roomkeys (
    roomkeyid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    roomcode public.citext CHECK (char_length(roomcode) <= 40),
    bldgnumber public.citext CHECK (char_length(bldgnumber) <= 10),
    roomid public.citext CHECK (char_length(roomid) <= 40),
    keycode public.citext CHECK (char_length(keycode) <= 60),
    holdername public.citext CHECK (char_length(holdername) <= 160),
    holdernetid public.citext CHECK (char_length(holdernetid) <= 64),
    issuedon public.citext CHECK (char_length(issuedon) <= 40),
    notes public.citext CHECK (char_length(notes) <= 300),
    keystate public.citext CHECK (char_length(keystate) <= 40),
    keytype public.citext CHECK (char_length(keytype) <= 60),
    quantity integer,
    surveycode public.citext CHECK (char_length(surveycode) <= 20),
    empstatus public.citext CHECK (char_length(empstatus) <= 40),
    assignedby public.citext CHECK (char_length(assignedby) <= 160),
    buildingtext public.citext CHECK (char_length(buildingtext) <= 160),
    floortext public.citext CHECK (char_length(floortext) <= 40),
    sourcelabel public.citext CHECK (char_length(sourcelabel) <= 60),
    returnedon public.citext CHECK (char_length(returnedon) <= 40),
    loston public.citext CHECK (char_length(loston) <= 40),
    updatedat timestamp(6),
    updatedbynetid public.citext CHECK (char_length(updatedbynetid) <= 64),
    ismanaged smallint NOT NULL DEFAULT 0,
    PRIMARY KEY (roomkeyid)
);
CREATE INDEX gis_roomkeys_ix_giskeys_room ON keys.gis_roomkeys (roomcode);
CREATE TABLE keys.ref_buildingaliases (
    aliasid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    buildingid integer NOT NULL,
    aliastext public.citext NOT NULL CHECK (char_length(aliastext) <= 200),
    aliasnorm public.citext NOT NULL CHECK (char_length(aliasnorm) <= 200),
    source public.citext NOT NULL DEFAULT 'seed' CHECK (char_length(source) <= 40),
    PRIMARY KEY (aliasid),
    CHECK (Source IN ('seed', 'legacy', 'fs', 'gis', 'manual'))
);
CREATE INDEX ref_buildingaliases_ix_aliases_norm ON keys.ref_buildingaliases (aliasnorm);
CREATE TABLE keys.ref_buildings (
    buildingid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    bldgnumber public.citext NOT NULL CHECK (char_length(bldgnumber) <= 10),
    sortkey public.citext NOT NULL CHECK (char_length(sortkey) <= 20),
    shortcode public.citext CHECK (char_length(shortcode) <= 20),
    name public.citext NOT NULL CHECK (char_length(name) <= 200),
    addressline public.citext CHECK (char_length(addressline) <= 200),
    city public.citext CHECK (char_length(city) <= 80),
    isoncampus smallint NOT NULL DEFAULT 1,
    isremote smallint NOT NULL DEFAULT 0,
    criticality integer NOT NULL DEFAULT 0,
    latitude numeric(9,6),
    longitude numeric(9,6),
    gisfeatureid public.citext CHECK (char_length(gisfeatureid) <= 64),
    requiresfreetext smallint NOT NULL DEFAULT 0,
    isactive smallint NOT NULL DEFAULT 1,
    name2 public.citext CHECK (char_length(name2) <= 300),
    addressname public.citext CHECK (char_length(addressname) <= 200),
    statecode public.citext CHECK (char_length(statecode) <= 10),
    postalcode public.citext CHECK (char_length(postalcode) <= 20),
    locationclass public.citext CHECK (char_length(locationclass) <= 30),
    buildingtype public.citext CHECK (char_length(buildingtype) <= 60),
    ownership public.citext CHECK (char_length(ownership) <= 40),
    condition public.citext CHECK (char_length(condition) <= 30),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    pripriority integer,
    PRIMARY KEY (buildingid),
    UNIQUE (bldgnumber)
);
CREATE INDEX ref_buildings_ix_buildings_sort ON keys.ref_buildings (sortkey);
CREATE TABLE keys.ref_owners (
    ownerid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    code public.citext NOT NULL CHECK (char_length(code) <= 20),
    name public.citext NOT NULL CHECK (char_length(name) <= 120),
    handoffemail public.citext CHECK (char_length(handoffemail) <= 200),
    handoffurl public.citext CHECK (char_length(handoffurl) <= 400),
    showsonboard smallint NOT NULL DEFAULT 1,
    PRIMARY KEY (ownerid),
    UNIQUE (code)
);
CREATE TABLE keys.ref_people (
    personid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    displayname public.citext NOT NULL CHECK (char_length(displayname) <= 160),
    email public.citext CHECK (char_length(email) <= 200),
    uin public.citext CHECK (char_length(uin) <= 40),
    surveycode public.citext CHECK (char_length(surveycode) <= 20),
    org public.citext CHECK (char_length(org) <= 200),
    position public.citext CHECK (char_length(position) <= 160),
    isactive smallint NOT NULL DEFAULT 1,
    sourcelabel public.citext CHECK (char_length(sourcelabel) <= 60),
    updatedat timestamp(6),
    firstname public.citext CHECK (char_length(firstname) <= 80),
    lastname public.citext CHECK (char_length(lastname) <= 80),
    orgpath public.citext CHECK (char_length(orgpath) <= 300),
    orgunit public.citext CHECK (char_length(orgunit) <= 120),
    orgrole public.citext CHECK (char_length(orgrole) <= 40),
    orgdepth integer,
    orgsince public.citext CHECK (char_length(orgsince) <= 40),
    positiontype public.citext CHECK (char_length(positiontype) <= 60),
    homebuilding public.citext CHECK (char_length(homebuilding) <= 60),
    homeroom public.citext CHECK (char_length(homeroom) <= 40),
    fieldstation public.citext CHECK (char_length(fieldstation) <= 120),
    roomtext public.citext CHECK (char_length(roomtext) <= 200),
    PRIMARY KEY (personid),
    UNIQUE (netid)
);
CREATE INDEX ref_people_ix_people_name ON keys.ref_people (displayname);
CREATE TABLE keys.ref_picklisttypes (
    listkey public.citext NOT NULL CHECK (char_length(listkey) <= 40),
    groupname public.citext NOT NULL CHECK (char_length(groupname) <= 60),
    title public.citext NOT NULL CHECK (char_length(title) <= 120),
    description public.citext CHECK (char_length(description) <= 400),
    usedon public.citext CHECK (char_length(usedon) <= 300),
    sortorder integer NOT NULL DEFAULT 100,
    PRIMARY KEY (listkey)
);
CREATE TABLE keys.ref_picklists (
    picklistid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    listkey public.citext NOT NULL CHECK (char_length(listkey) <= 40),
    code public.citext NOT NULL CHECK (char_length(code) <= 60),
    label public.citext NOT NULL CHECK (char_length(label) <= 160),
    sortorder integer NOT NULL DEFAULT 100,
    isactive smallint NOT NULL DEFAULT 1,
    note public.citext CHECK (char_length(note) <= 300),
    isprotected smallint NOT NULL DEFAULT 0,
    updatedat timestamp(6),
    updatedbynetid public.citext CHECK (char_length(updatedbynetid) <= 64),
    PRIMARY KEY (picklistid),
    UNIQUE (listkey, code)
);
CREATE INDEX ref_picklists_ix_picklists_list ON keys.ref_picklists (listkey, sortorder);
CREATE TABLE keys.ref_rooms (
    roomcode public.citext NOT NULL CHECK (char_length(roomcode) <= 40),
    bldgnumber public.citext NOT NULL CHECK (char_length(bldgnumber) <= 10),
    floorcode public.citext NOT NULL CHECK (char_length(floorcode) <= 10),
    roomid public.citext NOT NULL CHECK (char_length(roomid) <= 40),
    roomkey public.citext NOT NULL CHECK (char_length(roomkey) <= 40),
    roomname public.citext CHECK (char_length(roomname) <= 200),
    surveycode public.citext CHECK (char_length(surveycode) <= 20),
    PRIMARY KEY (roomcode)
);
CREATE INDEX ref_rooms_ix_refrooms_lookup ON keys.ref_rooms (bldgnumber, roomkey);
CREATE TABLE keys.ref_statusflow (
    requesttype public.citext NOT NULL CHECK (char_length(requesttype) <= 20),
    statuscode public.citext NOT NULL CHECK (char_length(statuscode) <= 30),
    stageorder integer NOT NULL,
    label public.citext NOT NULL CHECK (char_length(label) <= 60),
    description public.citext CHECK (char_length(description) <= 300),
    ownerhint public.citext CHECK (char_length(ownerhint) <= 60),
    isterminal smallint NOT NULL DEFAULT 0,
    notifysubmitter smallint NOT NULL DEFAULT 1,
    isactive smallint NOT NULL DEFAULT 1,
    PRIMARY KEY (requesttype, statuscode)
);
CREATE TABLE keys.ref_surveys (
    surveyid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    code public.citext NOT NULL CHECK (char_length(code) <= 10),
    name public.citext NOT NULL CHECK (char_length(name) <= 120),
    isactive smallint NOT NULL DEFAULT 1,
    directorname public.citext CHECK (char_length(directorname) <= 160),
    directoremail public.citext CHECK (char_length(directoremail) <= 200),
    proxyname public.citext CHECK (char_length(proxyname) <= 160),
    proxyemail public.citext CHECK (char_length(proxyemail) <= 200),
    notifydirector smallint NOT NULL DEFAULT 1,
    unitkind public.citext NOT NULL DEFAULT 'survey' CHECK (char_length(unitkind) <= 20),
    PRIMARY KEY (surveyid),
    UNIQUE (code)
);
CREATE TABLE keys.rq_approvals (
    approvalid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requesttype public.citext NOT NULL CHECK (char_length(requesttype) <= 10),
    requestid integer NOT NULL,
    stagecode public.citext NOT NULL CHECK (char_length(stagecode) <= 30),
    stageorder integer NOT NULL,
    approveruserid integer,
    approvername public.citext CHECK (char_length(approvername) <= 160),
    decision public.citext CHECK (char_length(decision) <= 20),
    decisionat timestamp(6),
    comment public.citext,
    returntostage public.citext CHECK (char_length(returntostage) <= 30),
    isrequired smallint NOT NULL DEFAULT 1,
    skipreason public.citext CHECK (char_length(skipreason) <= 120),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    fundingid integer,
    approveremail public.citext CHECK (char_length(approveremail) <= 200),
    PRIMARY KEY (approvalid),
    CHECK (Decision IN ('approved', 'denied', 'returned'))
);
CREATE INDEX rq_approvals_ix_rqapprovals ON keys.rq_approvals (requesttype, requestid, stageorder);
CREATE TABLE keys.rq_keyrequests (
    keyrequestid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    ticketnumber public.citext NOT NULL CHECK (char_length(ticketnumber) <= 24),
    requestedbyuserid integer NOT NULL,
    requestedbynetid public.citext NOT NULL CHECK (char_length(requestedbynetid) <= 64),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    holdername public.citext NOT NULL CHECK (char_length(holdername) <= 160),
    holdernetid public.citext CHECK (char_length(holdernetid) <= 64),
    empstatus public.citext CHECK (char_length(empstatus) <= 40),
    bldgnumber public.citext CHECK (char_length(bldgnumber) <= 10),
    floorcode public.citext CHECK (char_length(floorcode) <= 20),
    roomid public.citext CHECK (char_length(roomid) <= 40),
    roomcode public.citext CHECK (char_length(roomcode) <= 40),
    keytype public.citext CHECK (char_length(keytype) <= 60),
    quantity integer NOT NULL DEFAULT 1,
    requestkind public.citext NOT NULL DEFAULT 'new' CHECK (char_length(requestkind) <= 20),
    justification public.citext NOT NULL,
    neededbydate date,
    status public.citext NOT NULL DEFAULT 'submitted' CHECK (char_length(status) <= 30),
    decisionnote public.citext,
    issuedroomkeyid integer,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    updatedat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    closedat timestamp(6),
    PRIMARY KEY (keyrequestid),
    UNIQUE (ticketnumber),
    CHECK (RequestKind IN ('new', 'replacement', 'additional', 'return'))
);
CREATE INDEX rq_keyrequests_ix_keyreq_status ON keys.rq_keyrequests (status);

-- ==== register fleet (PRI_FacilitiesFleet) ====
CREATE SCHEMA fleet;
CREATE TABLE fleet.app_adminaccess (
    adminaccessid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    accessfunction public.citext NOT NULL DEFAULT 'facilities' CHECK (char_length(accessfunction) <= 30),
    note public.citext CHECK (char_length(note) <= 200),
    isactive smallint NOT NULL DEFAULT 1,
    grantedat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    grantedbynetid public.citext CHECK (char_length(grantedbynetid) <= 64),
    PRIMARY KEY (adminaccessid),
    UNIQUE (netid, surveycode, accessfunction),
    CHECK (AccessFunction IN ('director', 'proxy', 'facilities', 'safety', 'fleet', 'equipment', 'inventory', 'it', 'finance', 'deputy', 'executive'))
);
CREATE INDEX app_adminaccess_ix_adminaccess_netid ON fleet.app_adminaccess (netid, isactive);
CREATE TABLE fleet.app_attachments (
    attachmentid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    userid integer NOT NULL,
    storedname public.citext NOT NULL CHECK (char_length(storedname) <= 120),
    originalname public.citext NOT NULL CHECK (char_length(originalname) <= 260),
    mimetype public.citext NOT NULL CHECK (char_length(mimetype) <= 80),
    sizebytes bigint NOT NULL,
    exiflatitude numeric(9,6),
    exiflongitude numeric(9,6),
    capturedat timestamp(6),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    purpose public.citext NOT NULL DEFAULT 'photo' CHECK (char_length(purpose) <= 20),
    caption public.citext CHECK (char_length(caption) <= 300),
    requesttype public.citext CHECK (char_length(requesttype) <= 20),
    PRIMARY KEY (attachmentid),
    CHECK (Purpose IN ('photo', 'drawing', 'document', 'other'))
);
CREATE INDEX app_attachments_ix_attachments_request ON fleet.app_attachments (requestid);
CREATE TABLE fleet.app_auditlog (
    auditid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    userid integer,
    action public.citext NOT NULL CHECK (char_length(action) <= 60),
    targettype public.citext CHECK (char_length(targettype) <= 40),
    targetid public.citext CHECK (char_length(targetid) <= 40),
    detail public.citext,
    ipaddress public.citext CHECK (char_length(ipaddress) <= 45),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (auditid)
);
CREATE TABLE fleet.app_digestpreferences (
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    frequency public.citext NOT NULL DEFAULT 'weekly' CHECK (char_length(frequency) <= 10),
    sendday integer NOT NULL DEFAULT 1,
    sendhour integer NOT NULL DEFAULT 7,
    includemine smallint NOT NULL DEFAULT 1,
    token public.citext NOT NULL CHECK (char_length(token) <= 64),
    lastsentat timestamp(6),
    lastitemcount integer,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (netid),
    UNIQUE (token),
    CHECK (Frequency IN ('off', 'daily', 'weekly'))
);
CREATE TABLE fleet.app_notes (
    noteid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    userid integer NOT NULL,
    body public.citext NOT NULL,
    isinternal smallint NOT NULL DEFAULT 0,
    importbatchid integer,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (noteid)
);
CREATE INDEX app_notes_ix_notes_request ON fleet.app_notes (requestid);
CREATE TABLE fleet.app_notifications (
    notificationid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer,
    ticketnumber public.citext CHECK (char_length(ticketnumber) <= 24),
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 40),
    recipients public.citext NOT NULL,
    subject public.citext NOT NULL CHECK (char_length(subject) <= 300),
    body public.citext NOT NULL,
    status public.citext NOT NULL DEFAULT 'logged' CHECK (char_length(status) <= 20),
    errortext public.citext CHECK (char_length(errortext) <= 600),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    sentat timestamp(6),
    PRIMARY KEY (notificationid),
    CHECK (Status IN ('logged', 'sent', 'failed'))
);
CREATE INDEX app_notifications_ix_notifications_created ON fleet.app_notifications (createdat DESC);
CREATE TABLE fleet.app_notifyrules (
    ruleid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 40),
    matchtype public.citext NOT NULL DEFAULT 'always' CHECK (char_length(matchtype) <= 20),
    matchvalue public.citext CHECK (char_length(matchvalue) <= 120),
    email public.citext NOT NULL CHECK (char_length(email) <= 200),
    displayname public.citext CHECK (char_length(displayname) <= 160),
    note public.citext CHECK (char_length(note) <= 300),
    isactive smallint NOT NULL DEFAULT 1,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    createdbynetid public.citext CHECK (char_length(createdbynetid) <= 64),
    PRIMARY KEY (ruleid),
    CHECK (MatchType IN ('always', 'survey', 'work_type', 'owner', 'request_kind', 'severity_min', 'building', 'life_safety', 'specimen_risk'))
);
CREATE INDEX app_notifyrules_ix_notifyrules_event ON fleet.app_notifyrules (eventcode, isactive);
CREATE TABLE fleet.app_settings (
    settingkey public.citext NOT NULL CHECK (char_length(settingkey) <= 60),
    settingvalue public.citext NOT NULL CHECK (char_length(settingvalue) <= 400),
    valuetype public.citext NOT NULL DEFAULT 'number' CHECK (char_length(valuetype) <= 20),
    label public.citext NOT NULL CHECK (char_length(label) <= 160),
    helptext public.citext CHECK (char_length(helptext) <= 400),
    sortorder integer NOT NULL DEFAULT 0,
    PRIMARY KEY (settingkey)
);
CREATE TABLE fleet.app_statushistory (
    historyid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    fromstatus public.citext CHECK (char_length(fromstatus) <= 20),
    tostatus public.citext NOT NULL CHECK (char_length(tostatus) <= 20),
    userid integer,
    comment public.citext CHECK (char_length(comment) <= 600),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (historyid)
);
CREATE INDEX app_statushistory_ix_history_request ON fleet.app_statushistory (requestid);
CREATE TABLE fleet.app_users (
    userid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    displayname public.citext NOT NULL CHECK (char_length(displayname) <= 160),
    email public.citext NOT NULL CHECK (char_length(email) <= 200),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    unit public.citext CHECK (char_length(unit) <= 120),
    phone public.citext CHECK (char_length(phone) <= 40),
    role public.citext NOT NULL DEFAULT 'staff' CHECK (char_length(role) <= 20),
    isprovisional smallint NOT NULL DEFAULT 0,
    isactive smallint NOT NULL DEFAULT 1,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    lastloginat timestamp(6),
    PRIMARY KEY (userid),
    UNIQUE (netid),
    CHECK (Role IN ('staff', 'coordinator', 'approver', 'admin'))
);
CREATE TABLE fleet.ref_buildingaliases (
    aliasid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    buildingid integer NOT NULL,
    aliastext public.citext NOT NULL CHECK (char_length(aliastext) <= 200),
    aliasnorm public.citext NOT NULL CHECK (char_length(aliasnorm) <= 200),
    source public.citext NOT NULL DEFAULT 'seed' CHECK (char_length(source) <= 40),
    PRIMARY KEY (aliasid),
    CHECK (Source IN ('seed', 'legacy', 'fs', 'gis', 'manual'))
);
CREATE INDEX ref_buildingaliases_ix_aliases_norm ON fleet.ref_buildingaliases (aliasnorm);
CREATE TABLE fleet.ref_buildings (
    buildingid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    bldgnumber public.citext NOT NULL CHECK (char_length(bldgnumber) <= 10),
    sortkey public.citext NOT NULL CHECK (char_length(sortkey) <= 20),
    shortcode public.citext CHECK (char_length(shortcode) <= 20),
    name public.citext NOT NULL CHECK (char_length(name) <= 200),
    addressline public.citext CHECK (char_length(addressline) <= 200),
    city public.citext CHECK (char_length(city) <= 80),
    isoncampus smallint NOT NULL DEFAULT 1,
    isremote smallint NOT NULL DEFAULT 0,
    criticality integer NOT NULL DEFAULT 0,
    latitude numeric(9,6),
    longitude numeric(9,6),
    gisfeatureid public.citext CHECK (char_length(gisfeatureid) <= 64),
    requiresfreetext smallint NOT NULL DEFAULT 0,
    isactive smallint NOT NULL DEFAULT 1,
    name2 public.citext CHECK (char_length(name2) <= 300),
    addressname public.citext CHECK (char_length(addressname) <= 200),
    statecode public.citext CHECK (char_length(statecode) <= 10),
    postalcode public.citext CHECK (char_length(postalcode) <= 20),
    locationclass public.citext CHECK (char_length(locationclass) <= 30),
    buildingtype public.citext CHECK (char_length(buildingtype) <= 60),
    ownership public.citext CHECK (char_length(ownership) <= 40),
    condition public.citext CHECK (char_length(condition) <= 30),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    pripriority integer,
    PRIMARY KEY (buildingid),
    UNIQUE (bldgnumber)
);
CREATE INDEX ref_buildings_ix_buildings_sort ON fleet.ref_buildings (sortkey);
CREATE TABLE fleet.ref_driverformtypes (
    formcode public.citext NOT NULL CHECK (char_length(formcode) <= 30),
    title public.citext NOT NULL CHECK (char_length(title) <= 150),
    validmonths integer NOT NULL DEFAULT 12,
    isrequired smallint NOT NULL DEFAULT 1,
    wheretogetit public.citext CHECK (char_length(wheretogetit) <= 500),
    instructions public.citext CHECK (char_length(instructions) <= 1000),
    sortorder integer NOT NULL DEFAULT 100,
    isactive smallint NOT NULL DEFAULT 1,
    updatedat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    updatedbynetid public.citext CHECK (char_length(updatedbynetid) <= 50),
    PRIMARY KEY (formcode)
);
CREATE TABLE fleet.ref_fleetvehicles (
    fleetvehicleid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    fleetnumber public.citext NOT NULL CHECK (char_length(fleetnumber) <= 40),
    description public.citext NOT NULL CHECK (char_length(description) <= 200),
    vehicleyear integer,
    make public.citext CHECK (char_length(make) <= 60),
    model public.citext CHECK (char_length(model) <= 60),
    color public.citext CHECK (char_length(color) <= 40),
    platenumber public.citext CHECK (char_length(platenumber) <= 40),
    vin public.citext CHECK (char_length(vin) <= 40),
    homebldgnumber public.citext CHECK (char_length(homebldgnumber) <= 10),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    assignedto public.citext CHECK (char_length(assignedto) <= 160),
    isactive smallint NOT NULL DEFAULT 1,
    lastmiles integer,
    lastmileson date,
    PRIMARY KEY (fleetvehicleid),
    UNIQUE (fleetnumber)
);
CREATE INDEX ref_fleetvehicles_ix_fleet_active ON fleet.ref_fleetvehicles (isactive);
CREATE TABLE fleet.ref_owners (
    ownerid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    code public.citext NOT NULL CHECK (char_length(code) <= 20),
    name public.citext NOT NULL CHECK (char_length(name) <= 120),
    handoffemail public.citext CHECK (char_length(handoffemail) <= 200),
    handoffurl public.citext CHECK (char_length(handoffurl) <= 400),
    showsonboard smallint NOT NULL DEFAULT 1,
    PRIMARY KEY (ownerid),
    UNIQUE (code)
);
CREATE TABLE fleet.ref_people (
    personid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    displayname public.citext NOT NULL CHECK (char_length(displayname) <= 160),
    email public.citext CHECK (char_length(email) <= 200),
    uin public.citext CHECK (char_length(uin) <= 40),
    surveycode public.citext CHECK (char_length(surveycode) <= 20),
    org public.citext CHECK (char_length(org) <= 200),
    position public.citext CHECK (char_length(position) <= 160),
    isactive smallint NOT NULL DEFAULT 1,
    sourcelabel public.citext CHECK (char_length(sourcelabel) <= 60),
    updatedat timestamp(6),
    firstname public.citext CHECK (char_length(firstname) <= 80),
    lastname public.citext CHECK (char_length(lastname) <= 80),
    orgpath public.citext CHECK (char_length(orgpath) <= 300),
    orgunit public.citext CHECK (char_length(orgunit) <= 120),
    orgrole public.citext CHECK (char_length(orgrole) <= 40),
    orgdepth integer,
    orgsince public.citext CHECK (char_length(orgsince) <= 40),
    positiontype public.citext CHECK (char_length(positiontype) <= 60),
    homebuilding public.citext CHECK (char_length(homebuilding) <= 60),
    homeroom public.citext CHECK (char_length(homeroom) <= 40),
    fieldstation public.citext CHECK (char_length(fieldstation) <= 120),
    roomtext public.citext CHECK (char_length(roomtext) <= 200),
    PRIMARY KEY (personid),
    UNIQUE (netid)
);
CREATE INDEX ref_people_ix_people_name ON fleet.ref_people (displayname);
CREATE TABLE fleet.ref_picklisttypes (
    listkey public.citext NOT NULL CHECK (char_length(listkey) <= 40),
    groupname public.citext NOT NULL CHECK (char_length(groupname) <= 60),
    title public.citext NOT NULL CHECK (char_length(title) <= 120),
    description public.citext CHECK (char_length(description) <= 400),
    usedon public.citext CHECK (char_length(usedon) <= 300),
    sortorder integer NOT NULL DEFAULT 100,
    PRIMARY KEY (listkey)
);
CREATE TABLE fleet.ref_picklists (
    picklistid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    listkey public.citext NOT NULL CHECK (char_length(listkey) <= 40),
    code public.citext NOT NULL CHECK (char_length(code) <= 60),
    label public.citext NOT NULL CHECK (char_length(label) <= 160),
    sortorder integer NOT NULL DEFAULT 100,
    isactive smallint NOT NULL DEFAULT 1,
    note public.citext CHECK (char_length(note) <= 300),
    isprotected smallint NOT NULL DEFAULT 0,
    updatedat timestamp(6),
    updatedbynetid public.citext CHECK (char_length(updatedbynetid) <= 64),
    PRIMARY KEY (picklistid),
    UNIQUE (listkey, code)
);
CREATE INDEX ref_picklists_ix_picklists_list ON fleet.ref_picklists (listkey, sortorder);
CREATE TABLE fleet.ref_rooms (
    roomcode public.citext NOT NULL CHECK (char_length(roomcode) <= 40),
    bldgnumber public.citext NOT NULL CHECK (char_length(bldgnumber) <= 10),
    floorcode public.citext NOT NULL CHECK (char_length(floorcode) <= 10),
    roomid public.citext NOT NULL CHECK (char_length(roomid) <= 40),
    roomkey public.citext NOT NULL CHECK (char_length(roomkey) <= 40),
    roomname public.citext CHECK (char_length(roomname) <= 200),
    surveycode public.citext CHECK (char_length(surveycode) <= 20),
    PRIMARY KEY (roomcode)
);
CREATE INDEX ref_rooms_ix_refrooms_lookup ON fleet.ref_rooms (bldgnumber, roomkey);
CREATE TABLE fleet.ref_statusflow (
    requesttype public.citext NOT NULL CHECK (char_length(requesttype) <= 20),
    statuscode public.citext NOT NULL CHECK (char_length(statuscode) <= 30),
    stageorder integer NOT NULL,
    label public.citext NOT NULL CHECK (char_length(label) <= 60),
    description public.citext CHECK (char_length(description) <= 300),
    ownerhint public.citext CHECK (char_length(ownerhint) <= 60),
    isterminal smallint NOT NULL DEFAULT 0,
    notifysubmitter smallint NOT NULL DEFAULT 1,
    isactive smallint NOT NULL DEFAULT 1,
    PRIMARY KEY (requesttype, statuscode)
);
CREATE TABLE fleet.ref_surveys (
    surveyid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    code public.citext NOT NULL CHECK (char_length(code) <= 10),
    name public.citext NOT NULL CHECK (char_length(name) <= 120),
    isactive smallint NOT NULL DEFAULT 1,
    directorname public.citext CHECK (char_length(directorname) <= 160),
    directoremail public.citext CHECK (char_length(directoremail) <= 200),
    proxyname public.citext CHECK (char_length(proxyname) <= 160),
    proxyemail public.citext CHECK (char_length(proxyemail) <= 200),
    notifydirector smallint NOT NULL DEFAULT 1,
    unitkind public.citext NOT NULL DEFAULT 'survey' CHECK (char_length(unitkind) <= 20),
    PRIMARY KEY (surveyid),
    UNIQUE (code)
);
CREATE TABLE fleet.sh_driverforms (
    driverformid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    ticketnumber public.citext NOT NULL CHECK (char_length(ticketnumber) <= 30),
    netid public.citext NOT NULL CHECK (char_length(netid) <= 50),
    personname public.citext CHECK (char_length(personname) <= 150),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    formcode public.citext NOT NULL CHECK (char_length(formcode) <= 30),
    completedon date NOT NULL,
    expireson date,
    licencestate public.citext CHECK (char_length(licencestate) <= 10),
    licencenumberlast4 public.citext CHECK (char_length(licencenumberlast4) <= 8),
    status public.citext NOT NULL DEFAULT 'submitted' CHECK (char_length(status) <= 20),
    note public.citext CHECK (char_length(note) <= 1000),
    reviewnote public.citext CHECK (char_length(reviewnote) <= 1000),
    reviewedbynetid public.citext CHECK (char_length(reviewedbynetid) <= 50),
    reviewedat timestamp(6),
    submittedbynetid public.citext NOT NULL CHECK (char_length(submittedbynetid) <= 50),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    updatedat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (driverformid),
    UNIQUE (ticketnumber),
    CHECK (Status IN ('submitted', 'accepted', 'rejected', 'superseded'))
);
CREATE INDEX sh_driverforms_ix_driverforms_who ON fleet.sh_driverforms (netid, formcode, status);
CREATE INDEX sh_driverforms_ix_driverforms_expiry ON fleet.sh_driverforms (expireson);
CREATE TABLE fleet.sh_vehiclebookings (
    bookingid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    ticketnumber public.citext NOT NULL CHECK (char_length(ticketnumber) <= 30),
    fleetnumber public.citext NOT NULL CHECK (char_length(fleetnumber) <= 30),
    requestedbynetid public.citext NOT NULL CHECK (char_length(requestedbynetid) <= 50),
    requestedbyuserid integer,
    drivername public.citext NOT NULL CHECK (char_length(drivername) <= 150),
    drivernetid public.citext NOT NULL CHECK (char_length(drivernetid) <= 50),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    startsat timestamp(6) NOT NULL,
    endsat timestamp(6) NOT NULL,
    destination public.citext CHECK (char_length(destination) <= 300),
    purpose public.citext CHECK (char_length(purpose) <= 1000),
    passengercount integer,
    towingtrailer smallint NOT NULL DEFAULT 0,
    odometerout integer,
    odometerin integer,
    wentoutat timestamp(6),
    camebackat timestamp(6),
    status public.citext NOT NULL DEFAULT 'booked' CHECK (char_length(status) <= 20),
    note public.citext CHECK (char_length(note) <= 1000),
    cancelreason public.citext CHECK (char_length(cancelreason) <= 500),
    clearancenote public.citext CHECK (char_length(clearancenote) <= 500),
    clearedbyoverride public.citext CHECK (char_length(clearedbyoverride) <= 50),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    updatedat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (bookingid),
    UNIQUE (ticketnumber),
    CHECK (Status IN ('booked', 'out', 'returned', 'cancelled'))
);
CREATE INDEX sh_vehiclebookings_ix_vehiclebookings_when ON fleet.sh_vehiclebookings (fleetnumber, startsat, endsat);
CREATE INDEX sh_vehiclebookings_ix_vehiclebookings_driver ON fleet.sh_vehiclebookings (drivernetid, startsat DESC);
CREATE TABLE fleet.sh_vehiclereadings (
    readingid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    fleetnumber public.citext NOT NULL CHECK (char_length(fleetnumber) <= 30),
    miles integer NOT NULL,
    readon date NOT NULL,
    readbynetid public.citext NOT NULL CHECK (char_length(readbynetid) <= 50),
    readbyname public.citext CHECK (char_length(readbyname) <= 150),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    source public.citext NOT NULL DEFAULT 'manual' CHECK (char_length(source) <= 20),
    wassuggested smallint NOT NULL DEFAULT 0,
    suggestedmiles integer,
    photoattachmentid integer,
    note public.citext CHECK (char_length(note) <= 500),
    milessincelast integer,
    dayssincelast integer,
    isqueried smallint NOT NULL DEFAULT 0,
    querynote public.citext CHECK (char_length(querynote) <= 300),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (readingid),
    CHECK (Source IN ('qr', 'manual', 'booking', 'shop', 'import')),
    CHECK (Miles >= 0)
);
CREATE INDEX sh_vehiclereadings_ix_vehiclereadings_vehicle ON fleet.sh_vehiclereadings (fleetnumber, readon DESC, readingid DESC);

-- ==== register space (PRI_FacilitiesSpace) ====
CREATE SCHEMA space;
CREATE TABLE space.app_adminaccess (
    adminaccessid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    accessfunction public.citext NOT NULL DEFAULT 'facilities' CHECK (char_length(accessfunction) <= 30),
    note public.citext CHECK (char_length(note) <= 200),
    isactive smallint NOT NULL DEFAULT 1,
    grantedat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    grantedbynetid public.citext CHECK (char_length(grantedbynetid) <= 64),
    PRIMARY KEY (adminaccessid),
    UNIQUE (netid, surveycode, accessfunction),
    CHECK (AccessFunction IN ('director', 'proxy', 'facilities', 'safety', 'fleet', 'equipment', 'inventory', 'it', 'finance', 'deputy', 'executive'))
);
CREATE INDEX app_adminaccess_ix_adminaccess_netid ON space.app_adminaccess (netid, isactive);
CREATE TABLE space.app_attachments (
    attachmentid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    userid integer NOT NULL,
    storedname public.citext NOT NULL CHECK (char_length(storedname) <= 120),
    originalname public.citext NOT NULL CHECK (char_length(originalname) <= 260),
    mimetype public.citext NOT NULL CHECK (char_length(mimetype) <= 80),
    sizebytes bigint NOT NULL,
    exiflatitude numeric(9,6),
    exiflongitude numeric(9,6),
    capturedat timestamp(6),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    purpose public.citext NOT NULL DEFAULT 'photo' CHECK (char_length(purpose) <= 20),
    caption public.citext CHECK (char_length(caption) <= 300),
    requesttype public.citext CHECK (char_length(requesttype) <= 20),
    PRIMARY KEY (attachmentid),
    CHECK (Purpose IN ('photo', 'drawing', 'document', 'other'))
);
CREATE INDEX app_attachments_ix_attachments_request ON space.app_attachments (requestid);
CREATE TABLE space.app_auditlog (
    auditid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    userid integer,
    action public.citext NOT NULL CHECK (char_length(action) <= 60),
    targettype public.citext CHECK (char_length(targettype) <= 40),
    targetid public.citext CHECK (char_length(targetid) <= 40),
    detail public.citext,
    ipaddress public.citext CHECK (char_length(ipaddress) <= 45),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (auditid)
);
CREATE TABLE space.app_digestpreferences (
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    frequency public.citext NOT NULL DEFAULT 'weekly' CHECK (char_length(frequency) <= 10),
    sendday integer NOT NULL DEFAULT 1,
    sendhour integer NOT NULL DEFAULT 7,
    includemine smallint NOT NULL DEFAULT 1,
    token public.citext NOT NULL CHECK (char_length(token) <= 64),
    lastsentat timestamp(6),
    lastitemcount integer,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (netid),
    UNIQUE (token),
    CHECK (Frequency IN ('off', 'daily', 'weekly'))
);
CREATE TABLE space.app_notes (
    noteid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    userid integer NOT NULL,
    body public.citext NOT NULL,
    isinternal smallint NOT NULL DEFAULT 0,
    importbatchid integer,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (noteid)
);
CREATE INDEX app_notes_ix_notes_request ON space.app_notes (requestid);
CREATE TABLE space.app_notifications (
    notificationid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer,
    ticketnumber public.citext CHECK (char_length(ticketnumber) <= 24),
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 40),
    recipients public.citext NOT NULL,
    subject public.citext NOT NULL CHECK (char_length(subject) <= 300),
    body public.citext NOT NULL,
    status public.citext NOT NULL DEFAULT 'logged' CHECK (char_length(status) <= 20),
    errortext public.citext CHECK (char_length(errortext) <= 600),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    sentat timestamp(6),
    PRIMARY KEY (notificationid),
    CHECK (Status IN ('logged', 'sent', 'failed'))
);
CREATE INDEX app_notifications_ix_notifications_created ON space.app_notifications (createdat DESC);
CREATE TABLE space.app_notifyrules (
    ruleid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 40),
    matchtype public.citext NOT NULL DEFAULT 'always' CHECK (char_length(matchtype) <= 20),
    matchvalue public.citext CHECK (char_length(matchvalue) <= 120),
    email public.citext NOT NULL CHECK (char_length(email) <= 200),
    displayname public.citext CHECK (char_length(displayname) <= 160),
    note public.citext CHECK (char_length(note) <= 300),
    isactive smallint NOT NULL DEFAULT 1,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    createdbynetid public.citext CHECK (char_length(createdbynetid) <= 64),
    PRIMARY KEY (ruleid),
    CHECK (MatchType IN ('always', 'survey', 'work_type', 'owner', 'request_kind', 'severity_min', 'building', 'life_safety', 'specimen_risk'))
);
CREATE INDEX app_notifyrules_ix_notifyrules_event ON space.app_notifyrules (eventcode, isactive);
CREATE TABLE space.app_settings (
    settingkey public.citext NOT NULL CHECK (char_length(settingkey) <= 60),
    settingvalue public.citext NOT NULL CHECK (char_length(settingvalue) <= 400),
    valuetype public.citext NOT NULL DEFAULT 'number' CHECK (char_length(valuetype) <= 20),
    label public.citext NOT NULL CHECK (char_length(label) <= 160),
    helptext public.citext CHECK (char_length(helptext) <= 400),
    sortorder integer NOT NULL DEFAULT 0,
    PRIMARY KEY (settingkey)
);
CREATE TABLE space.app_statushistory (
    historyid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    fromstatus public.citext CHECK (char_length(fromstatus) <= 20),
    tostatus public.citext NOT NULL CHECK (char_length(tostatus) <= 20),
    userid integer,
    comment public.citext CHECK (char_length(comment) <= 600),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (historyid)
);
CREATE INDEX app_statushistory_ix_history_request ON space.app_statushistory (requestid);
CREATE TABLE space.app_users (
    userid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    displayname public.citext NOT NULL CHECK (char_length(displayname) <= 160),
    email public.citext NOT NULL CHECK (char_length(email) <= 200),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    unit public.citext CHECK (char_length(unit) <= 120),
    phone public.citext CHECK (char_length(phone) <= 40),
    role public.citext NOT NULL DEFAULT 'staff' CHECK (char_length(role) <= 20),
    isprovisional smallint NOT NULL DEFAULT 0,
    isactive smallint NOT NULL DEFAULT 1,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    lastloginat timestamp(6),
    PRIMARY KEY (userid),
    UNIQUE (netid),
    CHECK (Role IN ('staff', 'coordinator', 'approver', 'admin'))
);
CREATE TABLE space.ref_buildings (
    buildingid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    bldgnumber public.citext NOT NULL CHECK (char_length(bldgnumber) <= 10),
    sortkey public.citext NOT NULL CHECK (char_length(sortkey) <= 20),
    shortcode public.citext CHECK (char_length(shortcode) <= 20),
    name public.citext NOT NULL CHECK (char_length(name) <= 200),
    addressline public.citext CHECK (char_length(addressline) <= 200),
    city public.citext CHECK (char_length(city) <= 80),
    isoncampus smallint NOT NULL DEFAULT 1,
    isremote smallint NOT NULL DEFAULT 0,
    criticality integer NOT NULL DEFAULT 0,
    latitude numeric(9,6),
    longitude numeric(9,6),
    gisfeatureid public.citext CHECK (char_length(gisfeatureid) <= 64),
    requiresfreetext smallint NOT NULL DEFAULT 0,
    isactive smallint NOT NULL DEFAULT 1,
    name2 public.citext CHECK (char_length(name2) <= 300),
    addressname public.citext CHECK (char_length(addressname) <= 200),
    statecode public.citext CHECK (char_length(statecode) <= 10),
    postalcode public.citext CHECK (char_length(postalcode) <= 20),
    locationclass public.citext CHECK (char_length(locationclass) <= 30),
    buildingtype public.citext CHECK (char_length(buildingtype) <= 60),
    ownership public.citext CHECK (char_length(ownership) <= 40),
    condition public.citext CHECK (char_length(condition) <= 30),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    pripriority integer,
    PRIMARY KEY (buildingid),
    UNIQUE (bldgnumber)
);
CREATE INDEX ref_buildings_ix_buildings_sort ON space.ref_buildings (sortkey);
CREATE TABLE space.est_agreements (
    agreementid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    buildingid integer NOT NULL,
    bldgnumber public.citext NOT NULL CHECK (char_length(bldgnumber) <= 10),
    agreementkind public.citext NOT NULL CHECK (char_length(agreementkind) <= 30),
    reference public.citext CHECK (char_length(reference) <= 60),
    counterparty public.citext CHECK (char_length(counterparty) <= 200),
    title public.citext CHECK (char_length(title) <= 300),
    tenurestatus public.citext CHECK (char_length(tenurestatus) <= 60),
    termsbasis public.citext CHECK (char_length(termsbasis) <= 60),
    leasecostbasis public.citext CHECK (char_length(leasecostbasis) <= 60),
    omcostbasis public.citext CHECK (char_length(omcostbasis) <= 60),
    contractshare numeric(5,4),
    icrshare numeric(5,4),
    annualcost numeric(12,2),
    startson date,
    endson date,
    reviewdueon date,
    noticedays integer,
    status public.citext NOT NULL DEFAULT 'current' CHECK (char_length(status) <= 20),
    ownername public.citext CHECK (char_length(ownername) <= 150),
    ownernetid public.citext CHECK (char_length(ownernetid) <= 50),
    notes public.citext,
    sourcelabel public.citext CHECK (char_length(sourcelabel) <= 80),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    updatedat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    updatedbynetid public.citext CHECK (char_length(updatedbynetid) <= 64),
    PRIMARY KEY (agreementid),
    CHECK (Status IN ('draft', 'current', 'expired', 'superseded', 'ended', 'unknown')),
    CHECK ((ContractShare IS NULL AND IcrShare IS NULL) OR (ContractShare BETWEEN 0 AND 1 AND IcrShare BETWEEN 0 AND 1))
);
CREATE INDEX est_agreements_ix_agreements_building ON space.est_agreements (bldgnumber);
CREATE INDEX est_agreements_ix_agreements_due ON space.est_agreements (reviewdueon);
CREATE TABLE space.est_agreementevents (
    agreementeventid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    agreementid integer NOT NULL,
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 30),
    happenedon date,
    detail public.citext CHECK (char_length(detail) <= 1000),
    bynetid public.citext CHECK (char_length(bynetid) <= 50),
    byname public.citext CHECK (char_length(byname) <= 150),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (agreementeventid)
);
CREATE INDEX est_agreementevents_ix_agreementevents_agreement ON space.est_agreementevents (agreementid);
CREATE TABLE space.gis_buildingfootprints (
    bldgnumber public.citext NOT NULL CHECK (char_length(bldgnumber) <= 10),
    minx numeric(14,1),
    miny numeric(14,1),
    maxx numeric(14,1),
    maxy numeric(14,1),
    pathdata public.citext,
    PRIMARY KEY (bldgnumber)
);
CREATE TABLE space.gis_buildinginfo (
    bldgnumber public.citext NOT NULL CHECK (char_length(bldgnumber) <= 10),
    name1 public.citext CHECK (char_length(name1) <= 200),
    name2 public.citext CHECK (char_length(name2) <= 200),
    location public.citext CHECK (char_length(location) <= 80),
    addressline public.citext CHECK (char_length(addressline) <= 200),
    city public.citext CHECK (char_length(city) <= 80),
    state public.citext CHECK (char_length(state) <= 20),
    postalcode public.citext CHECK (char_length(postalcode) <= 20),
    longitude numeric(11,7),
    latitude numeric(11,7),
    PRIMARY KEY (bldgnumber)
);
CREATE TABLE space.gis_categorycolors (
    scope public.citext NOT NULL CHECK (char_length(scope) <= 20),
    categorycode public.citext NOT NULL CHECK (char_length(categorycode) <= 20),
    categoryname public.citext CHECK (char_length(categoryname) <= 120),
    red integer,
    green integer,
    blue integer,
    PRIMARY KEY (scope, categorycode)
);
CREATE TABLE space.gis_floors (
    bldgnumber public.citext NOT NULL CHECK (char_length(bldgnumber) <= 10),
    floorcode public.citext NOT NULL CHECK (char_length(floorcode) <= 10),
    minx numeric(14,1),
    miny numeric(14,1),
    maxx numeric(14,1),
    maxy numeric(14,1),
    wallpath public.citext,
    doorpath public.citext,
    PRIMARY KEY (bldgnumber, floorcode)
);
CREATE TABLE space.gis_occupants (
    occupantid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    roomcode public.citext CHECK (char_length(roomcode) <= 40),
    bldgnumber public.citext CHECK (char_length(bldgnumber) <= 10),
    floorcode public.citext CHECK (char_length(floorcode) <= 10),
    roomid public.citext CHECK (char_length(roomid) <= 40),
    personname public.citext CHECK (char_length(personname) <= 160),
    netid public.citext CHECK (char_length(netid) <= 64),
    uin public.citext CHECK (char_length(uin) <= 40),
    org public.citext CHECK (char_length(org) <= 200),
    emptype public.citext CHECK (char_length(emptype) <= 60),
    primaryoffice public.citext CHECK (char_length(primaryoffice) <= 10),
    confirmedon public.citext CHECK (char_length(confirmedon) <= 40),
    notes public.citext CHECK (char_length(notes) <= 300),
    ismanaged smallint NOT NULL DEFAULT 0,
    assignedon public.citext CHECK (char_length(assignedon) <= 40),
    endedon public.citext CHECK (char_length(endedon) <= 40),
    bynetid public.citext CHECK (char_length(bynetid) <= 64),
    PRIMARY KEY (occupantid)
);
CREATE INDEX gis_occupants_ix_gisocc_room ON space.gis_occupants (roomcode);
CREATE TABLE space.gis_roomassignmentevents (
    roomassignmenteventid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    roomcode public.citext NOT NULL CHECK (char_length(roomcode) <= 40),
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 30),
    detail public.citext CHECK (char_length(detail) <= 600),
    bynetid public.citext CHECK (char_length(bynetid) <= 64),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (roomassignmenteventid)
);
CREATE INDEX gis_roomassignmentevents_ix_gisroomassign ON space.gis_roomassignmentevents (roomcode, createdat);
CREATE TABLE space.gis_roomresponsibility (
    roomcode public.citext NOT NULL CHECK (char_length(roomcode) <= 40),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    principalinvestigator public.citext CHECK (char_length(principalinvestigator) <= 160),
    safetycontact public.citext CHECK (char_length(safetycontact) <= 160),
    notes public.citext CHECK (char_length(notes) <= 400),
    updatedat timestamp(6),
    updatedbynetid public.citext CHECK (char_length(updatedbynetid) <= 64),
    principalinvestigatornetid public.citext CHECK (char_length(principalinvestigatornetid) <= 64),
    safetycontactnetid public.citext CHECK (char_length(safetycontactnetid) <= 64),
    primarycontactnetid public.citext CHECK (char_length(primarycontactnetid) <= 64),
    roomuseoverride public.citext CHECK (char_length(roomuseoverride) <= 160),
    accessrestriction public.citext CHECK (char_length(accessrestriction) <= 120),
    PRIMARY KEY (roomcode)
);
CREATE TABLE space.gis_rooms (
    roomcode public.citext NOT NULL CHECK (char_length(roomcode) <= 40),
    bldgnumber public.citext NOT NULL CHECK (char_length(bldgnumber) <= 10),
    floorcode public.citext NOT NULL CHECK (char_length(floorcode) <= 10),
    roomid public.citext NOT NULL CHECK (char_length(roomid) <= 40),
    roomname public.citext CHECK (char_length(roomname) <= 200),
    collectiontype public.citext CHECK (char_length(collectiontype) <= 120),
    categorycode public.citext CHECK (char_length(categorycode) <= 20),
    categorydesc public.citext CHECK (char_length(categorydesc) <= 120),
    usecode public.citext CHECK (char_length(usecode) <= 20),
    usedesc public.citext CHECK (char_length(usedesc) <= 160),
    department public.citext CHECK (char_length(department) <= 120),
    division public.citext CHECK (char_length(division) <= 120),
    divisionname public.citext CHECK (char_length(divisionname) <= 200),
    areasqft numeric(12,1),
    centroidx numeric(12,1),
    centroidy numeric(12,1),
    pathdata public.citext,
    otherdescription public.citext CHECK (char_length(otherdescription) <= 300),
    drsinspect public.citext CHECK (char_length(drsinspect) <= 40),
    collectionreport public.citext CHECK (char_length(collectionreport) <= 40),
    category02 public.citext CHECK (char_length(category02) <= 20),
    desc02 public.citext CHECK (char_length(desc02) <= 160),
    spacepercent numeric(6,2),
    splitspace public.citext CHECK (char_length(splitspace) <= 40),
    surveycode public.citext CHECK (char_length(surveycode) <= 20),
    org1 public.citext CHECK (char_length(org1) <= 200),
    org1a public.citext CHECK (char_length(org1a) <= 200),
    org3a public.citext CHECK (char_length(org3a) <= 200),
    org4a public.citext CHECK (char_length(org4a) <= 200),
    keycoderoom public.citext CHECK (char_length(keycoderoom) <= 40),
    keycodebuilding public.citext CHECK (char_length(keycodebuilding) <= 40),
    PRIMARY KEY (roomcode)
);
CREATE INDEX gis_rooms_ix_gisrooms_bldg ON space.gis_rooms (bldgnumber, floorcode);
CREATE INDEX gis_rooms_ix_gisrooms_room ON space.gis_rooms (bldgnumber, roomid);
CREATE TABLE space.gis_safety (
    safetyid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    roomcode public.citext CHECK (char_length(roomcode) <= 40),
    bldgnumber public.citext CHECK (char_length(bldgnumber) <= 10),
    roomid public.citext CHECK (char_length(roomid) <= 40),
    kind public.citext NOT NULL CHECK (char_length(kind) <= 40),
    tag public.citext CHECK (char_length(tag) <= 60),
    brand public.citext CHECK (char_length(brand) <= 80),
    model public.citext CHECK (char_length(model) <= 80),
    serialnumber public.citext CHECK (char_length(serialnumber) <= 80),
    descriptor public.citext CHECK (char_length(descriptor) <= 200),
    status public.citext CHECK (char_length(status) <= 60),
    lasttested public.citext CHECK (char_length(lasttested) <= 40),
    nextdue public.citext CHECK (char_length(nextdue) <= 40),
    ismanaged smallint NOT NULL DEFAULT 0,
    updatedat timestamp(6),
    updatedbynetid public.citext CHECK (char_length(updatedbynetid) <= 64),
    PRIMARY KEY (safetyid)
);
CREATE INDEX gis_safety_ix_gissafety_room ON space.gis_safety (roomcode);
CREATE TABLE space.ref_buildingaliases (
    aliasid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    buildingid integer NOT NULL,
    aliastext public.citext NOT NULL CHECK (char_length(aliastext) <= 200),
    aliasnorm public.citext NOT NULL CHECK (char_length(aliasnorm) <= 200),
    source public.citext NOT NULL DEFAULT 'seed' CHECK (char_length(source) <= 40),
    PRIMARY KEY (aliasid),
    CHECK (Source IN ('seed', 'legacy', 'fs', 'gis', 'manual'))
);
CREATE INDEX ref_buildingaliases_ix_aliases_norm ON space.ref_buildingaliases (aliasnorm);
CREATE TABLE space.ref_buildingmaps (
    buildingmapid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    bldgnumber public.citext NOT NULL CHECK (char_length(bldgnumber) <= 10),
    floorcode public.citext NOT NULL CHECK (char_length(floorcode) <= 20),
    floorlabel public.citext NOT NULL CHECK (char_length(floorlabel) <= 60),
    serviceurl public.citext NOT NULL CHECK (char_length(serviceurl) <= 400),
    roomlayerid integer NOT NULL DEFAULT 1,
    sortorder integer NOT NULL DEFAULT 0,
    isactive smallint NOT NULL DEFAULT 1,
    PRIMARY KEY (buildingmapid),
    UNIQUE (bldgnumber, floorcode)
);
CREATE TABLE space.ref_surveys (
    surveyid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    code public.citext NOT NULL CHECK (char_length(code) <= 10),
    name public.citext NOT NULL CHECK (char_length(name) <= 120),
    isactive smallint NOT NULL DEFAULT 1,
    directorname public.citext CHECK (char_length(directorname) <= 160),
    directoremail public.citext CHECK (char_length(directoremail) <= 200),
    proxyname public.citext CHECK (char_length(proxyname) <= 160),
    proxyemail public.citext CHECK (char_length(proxyemail) <= 200),
    notifydirector smallint NOT NULL DEFAULT 1,
    unitkind public.citext NOT NULL DEFAULT 'survey' CHECK (char_length(unitkind) <= 20),
    PRIMARY KEY (surveyid),
    UNIQUE (code)
);
CREATE TABLE space.ref_buildingoccupants (
    buildingid integer NOT NULL,
    surveyid integer NOT NULL,
    isprimary smallint NOT NULL DEFAULT 0,
    PRIMARY KEY (buildingid, surveyid)
);
CREATE TABLE space.ref_owners (
    ownerid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    code public.citext NOT NULL CHECK (char_length(code) <= 20),
    name public.citext NOT NULL CHECK (char_length(name) <= 120),
    handoffemail public.citext CHECK (char_length(handoffemail) <= 200),
    handoffurl public.citext CHECK (char_length(handoffurl) <= 400),
    showsonboard smallint NOT NULL DEFAULT 1,
    PRIMARY KEY (ownerid),
    UNIQUE (code)
);
CREATE TABLE space.ref_people (
    personid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    displayname public.citext NOT NULL CHECK (char_length(displayname) <= 160),
    email public.citext CHECK (char_length(email) <= 200),
    uin public.citext CHECK (char_length(uin) <= 40),
    surveycode public.citext CHECK (char_length(surveycode) <= 20),
    org public.citext CHECK (char_length(org) <= 200),
    position public.citext CHECK (char_length(position) <= 160),
    isactive smallint NOT NULL DEFAULT 1,
    sourcelabel public.citext CHECK (char_length(sourcelabel) <= 60),
    updatedat timestamp(6),
    firstname public.citext CHECK (char_length(firstname) <= 80),
    lastname public.citext CHECK (char_length(lastname) <= 80),
    orgpath public.citext CHECK (char_length(orgpath) <= 300),
    orgunit public.citext CHECK (char_length(orgunit) <= 120),
    orgrole public.citext CHECK (char_length(orgrole) <= 40),
    orgdepth integer,
    orgsince public.citext CHECK (char_length(orgsince) <= 40),
    positiontype public.citext CHECK (char_length(positiontype) <= 60),
    homebuilding public.citext CHECK (char_length(homebuilding) <= 60),
    homeroom public.citext CHECK (char_length(homeroom) <= 40),
    fieldstation public.citext CHECK (char_length(fieldstation) <= 120),
    roomtext public.citext CHECK (char_length(roomtext) <= 200),
    PRIMARY KEY (personid),
    UNIQUE (netid)
);
CREATE INDEX ref_people_ix_people_name ON space.ref_people (displayname);
CREATE TABLE space.ref_picklisttypes (
    listkey public.citext NOT NULL CHECK (char_length(listkey) <= 40),
    groupname public.citext NOT NULL CHECK (char_length(groupname) <= 60),
    title public.citext NOT NULL CHECK (char_length(title) <= 120),
    description public.citext CHECK (char_length(description) <= 400),
    usedon public.citext CHECK (char_length(usedon) <= 300),
    sortorder integer NOT NULL DEFAULT 100,
    PRIMARY KEY (listkey)
);
CREATE TABLE space.ref_picklists (
    picklistid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    listkey public.citext NOT NULL CHECK (char_length(listkey) <= 40),
    code public.citext NOT NULL CHECK (char_length(code) <= 60),
    label public.citext NOT NULL CHECK (char_length(label) <= 160),
    sortorder integer NOT NULL DEFAULT 100,
    isactive smallint NOT NULL DEFAULT 1,
    note public.citext CHECK (char_length(note) <= 300),
    isprotected smallint NOT NULL DEFAULT 0,
    updatedat timestamp(6),
    updatedbynetid public.citext CHECK (char_length(updatedbynetid) <= 64),
    PRIMARY KEY (picklistid),
    UNIQUE (listkey, code)
);
CREATE INDEX ref_picklists_ix_picklists_list ON space.ref_picklists (listkey, sortorder);
CREATE TABLE space.ref_rooms (
    roomcode public.citext NOT NULL CHECK (char_length(roomcode) <= 40),
    bldgnumber public.citext NOT NULL CHECK (char_length(bldgnumber) <= 10),
    floorcode public.citext NOT NULL CHECK (char_length(floorcode) <= 10),
    roomid public.citext NOT NULL CHECK (char_length(roomid) <= 40),
    roomkey public.citext NOT NULL CHECK (char_length(roomkey) <= 40),
    roomname public.citext CHECK (char_length(roomname) <= 200),
    surveycode public.citext CHECK (char_length(surveycode) <= 20),
    PRIMARY KEY (roomcode)
);
CREATE INDEX ref_rooms_ix_refrooms_lookup ON space.ref_rooms (bldgnumber, roomkey);
CREATE TABLE space.ref_statusflow (
    requesttype public.citext NOT NULL CHECK (char_length(requesttype) <= 20),
    statuscode public.citext NOT NULL CHECK (char_length(statuscode) <= 30),
    stageorder integer NOT NULL,
    label public.citext NOT NULL CHECK (char_length(label) <= 60),
    description public.citext CHECK (char_length(description) <= 300),
    ownerhint public.citext CHECK (char_length(ownerhint) <= 60),
    isterminal smallint NOT NULL DEFAULT 0,
    notifysubmitter smallint NOT NULL DEFAULT 1,
    isactive smallint NOT NULL DEFAULT 1,
    PRIMARY KEY (requesttype, statuscode)
);
CREATE TABLE space.rq_approvals (
    approvalid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requesttype public.citext NOT NULL CHECK (char_length(requesttype) <= 10),
    requestid integer NOT NULL,
    stagecode public.citext NOT NULL CHECK (char_length(stagecode) <= 30),
    stageorder integer NOT NULL,
    approveruserid integer,
    approvername public.citext CHECK (char_length(approvername) <= 160),
    decision public.citext CHECK (char_length(decision) <= 20),
    decisionat timestamp(6),
    comment public.citext,
    returntostage public.citext CHECK (char_length(returntostage) <= 30),
    isrequired smallint NOT NULL DEFAULT 1,
    skipreason public.citext CHECK (char_length(skipreason) <= 120),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    fundingid integer,
    approveremail public.citext CHECK (char_length(approveremail) <= 200),
    PRIMARY KEY (approvalid),
    CHECK (Decision IN ('approved', 'denied', 'returned'))
);
CREATE INDEX rq_approvals_ix_rqapprovals ON space.rq_approvals (requesttype, requestid, stageorder);
CREATE TABLE space.rq_spacerequests (
    spacerequestid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    ticketnumber public.citext NOT NULL CHECK (char_length(ticketnumber) <= 24),
    requestedbyuserid integer NOT NULL,
    requestedbynetid public.citext NOT NULL CHECK (char_length(requestedbynetid) <= 64),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    requestkind public.citext NOT NULL DEFAULT 'additional' CHECK (char_length(requestkind) <= 30),
    currentroomcode public.citext CHECK (char_length(currentroomcode) <= 40),
    currentbldgnumber public.citext CHECK (char_length(currentbldgnumber) <= 10),
    currentroomid public.citext CHECK (char_length(currentroomid) <= 40),
    requestedbldgnumber public.citext CHECK (char_length(requestedbldgnumber) <= 10),
    requestedroomid public.citext CHECK (char_length(requestedroomid) <= 40),
    requestedroomcode public.citext CHECK (char_length(requestedroomcode) <= 40),
    peopleaffected integer,
    spaceuse public.citext CHECK (char_length(spaceuse) <= 120),
    neededbydate date,
    justification public.citext NOT NULL,
    status public.citext NOT NULL DEFAULT 'submitted' CHECK (char_length(status) <= 30),
    decisionnote public.citext,
    assignedroomcode public.citext CHECK (char_length(assignedroomcode) <= 40),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    updatedat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    closedat timestamp(6),
    submittedbynames public.citext CHECK (char_length(submittedbynames) <= 300),
    requesteremail public.citext CHECK (char_length(requesteremail) <= 200),
    staffaffected public.citext,
    requestedchange public.citext,
    potentialcosts public.citext CHECK (char_length(potentialcosts) <= 300),
    fundingsource public.citext CHECK (char_length(fundingsource) <= 300),
    spacetype public.citext CHECK (char_length(spacetype) <= 60),
    spacetypeother public.citext CHECK (char_length(spacetypeother) <= 200),
    fundingcfop public.citext CHECK (char_length(fundingcfop) <= 40),
    fundingpi public.citext CHECK (char_length(fundingpi) <= 200),
    fundingfundmanager public.citext CHECK (char_length(fundingfundmanager) <= 200),
    fundingsurveycode public.citext CHECK (char_length(fundingsurveycode) <= 20),
    fundingdescription public.citext CHECK (char_length(fundingdescription) <= 300),
    submitternetid public.citext CHECK (char_length(submitternetid) <= 64),
    submittersurvey public.citext CHECK (char_length(submittersurvey) <= 20),
    PRIMARY KEY (spacerequestid),
    UNIQUE (ticketnumber),
    CHECK (RequestKind IN ('additional', 'change_use', 'relocate', 'release', 'shared')),
    CHECK (SpaceType IS NULL OR SpaceType IN ('office', 'lab', 'collections', 'storage', 'instrument', 'processing', 'shop', 'growing', 'meeting', 'greenhouse', 'other'))
);
CREATE INDEX rq_spacerequests_ix_spacereq_status ON space.rq_spacerequests (status);

-- ==== register equipment (PRI_FacilitiesEquipment) ====
CREATE SCHEMA equipment;
CREATE TABLE equipment.app_adminaccess (
    adminaccessid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    accessfunction public.citext NOT NULL DEFAULT 'facilities' CHECK (char_length(accessfunction) <= 30),
    note public.citext CHECK (char_length(note) <= 200),
    isactive smallint NOT NULL DEFAULT 1,
    grantedat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    grantedbynetid public.citext CHECK (char_length(grantedbynetid) <= 64),
    PRIMARY KEY (adminaccessid),
    UNIQUE (netid, surveycode, accessfunction),
    CHECK (AccessFunction IN ('director', 'proxy', 'facilities', 'safety', 'fleet', 'equipment', 'inventory', 'it', 'finance', 'deputy', 'executive'))
);
CREATE INDEX app_adminaccess_ix_adminaccess_netid ON equipment.app_adminaccess (netid, isactive);
CREATE TABLE equipment.app_attachments (
    attachmentid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    userid integer NOT NULL,
    storedname public.citext NOT NULL CHECK (char_length(storedname) <= 120),
    originalname public.citext NOT NULL CHECK (char_length(originalname) <= 260),
    mimetype public.citext NOT NULL CHECK (char_length(mimetype) <= 80),
    sizebytes bigint NOT NULL,
    exiflatitude numeric(9,6),
    exiflongitude numeric(9,6),
    capturedat timestamp(6),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    purpose public.citext NOT NULL DEFAULT 'photo' CHECK (char_length(purpose) <= 20),
    caption public.citext CHECK (char_length(caption) <= 300),
    requesttype public.citext CHECK (char_length(requesttype) <= 20),
    PRIMARY KEY (attachmentid),
    CHECK (Purpose IN ('photo', 'drawing', 'document', 'other'))
);
CREATE INDEX app_attachments_ix_attachments_request ON equipment.app_attachments (requestid);
CREATE TABLE equipment.app_auditlog (
    auditid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    userid integer,
    action public.citext NOT NULL CHECK (char_length(action) <= 60),
    targettype public.citext CHECK (char_length(targettype) <= 40),
    targetid public.citext CHECK (char_length(targetid) <= 40),
    detail public.citext,
    ipaddress public.citext CHECK (char_length(ipaddress) <= 45),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (auditid)
);
CREATE TABLE equipment.app_digestpreferences (
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    frequency public.citext NOT NULL DEFAULT 'weekly' CHECK (char_length(frequency) <= 10),
    sendday integer NOT NULL DEFAULT 1,
    sendhour integer NOT NULL DEFAULT 7,
    includemine smallint NOT NULL DEFAULT 1,
    token public.citext NOT NULL CHECK (char_length(token) <= 64),
    lastsentat timestamp(6),
    lastitemcount integer,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (netid),
    UNIQUE (token),
    CHECK (Frequency IN ('off', 'daily', 'weekly'))
);
CREATE TABLE equipment.app_notes (
    noteid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    userid integer NOT NULL,
    body public.citext NOT NULL,
    isinternal smallint NOT NULL DEFAULT 0,
    importbatchid integer,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (noteid)
);
CREATE INDEX app_notes_ix_notes_request ON equipment.app_notes (requestid);
CREATE TABLE equipment.app_notifications (
    notificationid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer,
    ticketnumber public.citext CHECK (char_length(ticketnumber) <= 24),
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 40),
    recipients public.citext NOT NULL,
    subject public.citext NOT NULL CHECK (char_length(subject) <= 300),
    body public.citext NOT NULL,
    status public.citext NOT NULL DEFAULT 'logged' CHECK (char_length(status) <= 20),
    errortext public.citext CHECK (char_length(errortext) <= 600),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    sentat timestamp(6),
    PRIMARY KEY (notificationid),
    CHECK (Status IN ('logged', 'sent', 'failed'))
);
CREATE INDEX app_notifications_ix_notifications_created ON equipment.app_notifications (createdat DESC);
CREATE TABLE equipment.app_notifyrules (
    ruleid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 40),
    matchtype public.citext NOT NULL DEFAULT 'always' CHECK (char_length(matchtype) <= 20),
    matchvalue public.citext CHECK (char_length(matchvalue) <= 120),
    email public.citext NOT NULL CHECK (char_length(email) <= 200),
    displayname public.citext CHECK (char_length(displayname) <= 160),
    note public.citext CHECK (char_length(note) <= 300),
    isactive smallint NOT NULL DEFAULT 1,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    createdbynetid public.citext CHECK (char_length(createdbynetid) <= 64),
    PRIMARY KEY (ruleid),
    CHECK (MatchType IN ('always', 'survey', 'work_type', 'owner', 'request_kind', 'severity_min', 'building', 'life_safety', 'specimen_risk'))
);
CREATE INDEX app_notifyrules_ix_notifyrules_event ON equipment.app_notifyrules (eventcode, isactive);
CREATE TABLE equipment.app_settings (
    settingkey public.citext NOT NULL CHECK (char_length(settingkey) <= 60),
    settingvalue public.citext NOT NULL CHECK (char_length(settingvalue) <= 400),
    valuetype public.citext NOT NULL DEFAULT 'number' CHECK (char_length(valuetype) <= 20),
    label public.citext NOT NULL CHECK (char_length(label) <= 160),
    helptext public.citext CHECK (char_length(helptext) <= 400),
    sortorder integer NOT NULL DEFAULT 0,
    PRIMARY KEY (settingkey)
);
CREATE TABLE equipment.app_statushistory (
    historyid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    fromstatus public.citext CHECK (char_length(fromstatus) <= 20),
    tostatus public.citext NOT NULL CHECK (char_length(tostatus) <= 20),
    userid integer,
    comment public.citext CHECK (char_length(comment) <= 600),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (historyid)
);
CREATE INDEX app_statushistory_ix_history_request ON equipment.app_statushistory (requestid);
CREATE TABLE equipment.app_users (
    userid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    displayname public.citext NOT NULL CHECK (char_length(displayname) <= 160),
    email public.citext NOT NULL CHECK (char_length(email) <= 200),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    unit public.citext CHECK (char_length(unit) <= 120),
    phone public.citext CHECK (char_length(phone) <= 40),
    role public.citext NOT NULL DEFAULT 'staff' CHECK (char_length(role) <= 20),
    isprovisional smallint NOT NULL DEFAULT 0,
    isactive smallint NOT NULL DEFAULT 1,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    lastloginat timestamp(6),
    PRIMARY KEY (userid),
    UNIQUE (netid),
    CHECK (Role IN ('staff', 'coordinator', 'approver', 'admin'))
);
CREATE TABLE equipment.gis_inventory (
    inventoryid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    roomcode public.citext CHECK (char_length(roomcode) <= 40),
    bldgnumber public.citext CHECK (char_length(bldgnumber) <= 10),
    bannerroom public.citext CHECK (char_length(bannerroom) <= 40),
    propertytag public.citext CHECK (char_length(propertytag) <= 40),
    description public.citext CHECK (char_length(description) <= 300),
    model public.citext CHECK (char_length(model) <= 120),
    serialnumber public.citext CHECK (char_length(serialnumber) <= 120),
    person public.citext CHECK (char_length(person) <= 160),
    acquiredon public.citext CHECK (char_length(acquiredon) <= 40),
    cost numeric(14,2),
    depreciatedvalue numeric(14,2),
    fundingsource public.citext CHECK (char_length(fundingsource) <= 200),
    bannerlocationcode public.citext CHECK (char_length(bannerlocationcode) <= 40),
    status public.citext NOT NULL DEFAULT 'active' CHECK (char_length(status) <= 20),
    roomid public.citext CHECK (char_length(roomid) <= 40),
    condition public.citext CHECK (char_length(condition) <= 40),
    surveycode public.citext CHECK (char_length(surveycode) <= 20),
    lastmovedat timestamp(6),
    removedon public.citext CHECK (char_length(removedon) <= 40),
    removalreason public.citext CHECK (char_length(removalreason) <= 300),
    ismanaged smallint NOT NULL DEFAULT 0,
    updatedat timestamp(6),
    updatedbynetid public.citext CHECK (char_length(updatedbynetid) <= 64),
    salvagevalue numeric(12,2),
    equipclass public.citext CHECK (char_length(equipclass) <= 30),
    purchasedocument public.citext CHECK (char_length(purchasedocument) <= 60),
    ponumber public.citext CHECK (char_length(ponumber) <= 30),
    requisitionnumber public.citext CHECK (char_length(requisitionnumber) <= 30),
    purchasedockind public.citext CHECK (char_length(purchasedockind) <= 12),
    accumulateddepreciation numeric(14,2),
    PRIMARY KEY (inventoryid),
    CHECK (Status IN ('active', 'returned', 'surplus', 'trashed', 'lost', 'transferred', 'traded', 'cannibalised'))
);
CREATE INDEX gis_inventory_ix_gisinv_room ON equipment.gis_inventory (roomcode);
CREATE INDEX gis_inventory_ix_gisinv_bldg ON equipment.gis_inventory (bldgnumber);
CREATE TABLE equipment.gis_inventoryevents (
    inventoryeventid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    inventoryid integer NOT NULL,
    propertytag public.citext CHECK (char_length(propertytag) <= 40),
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 20),
    fromroomcode public.citext CHECK (char_length(fromroomcode) <= 40),
    toroomcode public.citext CHECK (char_length(toroomcode) <= 40),
    frombldgnumber public.citext CHECK (char_length(frombldgnumber) <= 10),
    tobldgnumber public.citext CHECK (char_length(tobldgnumber) <= 10),
    detail public.citext CHECK (char_length(detail) <= 600),
    moveticket public.citext CHECK (char_length(moveticket) <= 24),
    bynetid public.citext CHECK (char_length(bynetid) <= 64),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (inventoryeventid),
    CHECK (EventCode IN ('ingested', 'registered', 'moved', 'reassigned', 'transferred', 'corrected', 'edited', 'removed', 'restored'))
);
CREATE INDEX gis_inventoryevents_ix_gisinvevents ON equipment.gis_inventoryevents (inventoryid, createdat);
CREATE INDEX gis_inventoryevents_ix_gisinvevents_tag ON equipment.gis_inventoryevents (propertytag);
CREATE TABLE equipment.ref_buildingaliases (
    aliasid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    buildingid integer NOT NULL,
    aliastext public.citext NOT NULL CHECK (char_length(aliastext) <= 200),
    aliasnorm public.citext NOT NULL CHECK (char_length(aliasnorm) <= 200),
    source public.citext NOT NULL DEFAULT 'seed' CHECK (char_length(source) <= 40),
    PRIMARY KEY (aliasid),
    CHECK (Source IN ('seed', 'legacy', 'fs', 'gis', 'manual'))
);
CREATE INDEX ref_buildingaliases_ix_aliases_norm ON equipment.ref_buildingaliases (aliasnorm);
CREATE TABLE equipment.ref_buildings (
    buildingid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    bldgnumber public.citext NOT NULL CHECK (char_length(bldgnumber) <= 10),
    sortkey public.citext NOT NULL CHECK (char_length(sortkey) <= 20),
    shortcode public.citext CHECK (char_length(shortcode) <= 20),
    name public.citext NOT NULL CHECK (char_length(name) <= 200),
    addressline public.citext CHECK (char_length(addressline) <= 200),
    city public.citext CHECK (char_length(city) <= 80),
    isoncampus smallint NOT NULL DEFAULT 1,
    isremote smallint NOT NULL DEFAULT 0,
    criticality integer NOT NULL DEFAULT 0,
    latitude numeric(9,6),
    longitude numeric(9,6),
    gisfeatureid public.citext CHECK (char_length(gisfeatureid) <= 64),
    requiresfreetext smallint NOT NULL DEFAULT 0,
    isactive smallint NOT NULL DEFAULT 1,
    name2 public.citext CHECK (char_length(name2) <= 300),
    addressname public.citext CHECK (char_length(addressname) <= 200),
    statecode public.citext CHECK (char_length(statecode) <= 10),
    postalcode public.citext CHECK (char_length(postalcode) <= 20),
    locationclass public.citext CHECK (char_length(locationclass) <= 30),
    buildingtype public.citext CHECK (char_length(buildingtype) <= 60),
    ownership public.citext CHECK (char_length(ownership) <= 40),
    condition public.citext CHECK (char_length(condition) <= 30),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    pripriority integer,
    PRIMARY KEY (buildingid),
    UNIQUE (bldgnumber)
);
CREATE INDEX ref_buildings_ix_buildings_sort ON equipment.ref_buildings (sortkey);
CREATE TABLE equipment.ref_owners (
    ownerid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    code public.citext NOT NULL CHECK (char_length(code) <= 20),
    name public.citext NOT NULL CHECK (char_length(name) <= 120),
    handoffemail public.citext CHECK (char_length(handoffemail) <= 200),
    handoffurl public.citext CHECK (char_length(handoffurl) <= 400),
    showsonboard smallint NOT NULL DEFAULT 1,
    PRIMARY KEY (ownerid),
    UNIQUE (code)
);
CREATE TABLE equipment.ref_people (
    personid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    displayname public.citext NOT NULL CHECK (char_length(displayname) <= 160),
    email public.citext CHECK (char_length(email) <= 200),
    uin public.citext CHECK (char_length(uin) <= 40),
    surveycode public.citext CHECK (char_length(surveycode) <= 20),
    org public.citext CHECK (char_length(org) <= 200),
    position public.citext CHECK (char_length(position) <= 160),
    isactive smallint NOT NULL DEFAULT 1,
    sourcelabel public.citext CHECK (char_length(sourcelabel) <= 60),
    updatedat timestamp(6),
    firstname public.citext CHECK (char_length(firstname) <= 80),
    lastname public.citext CHECK (char_length(lastname) <= 80),
    orgpath public.citext CHECK (char_length(orgpath) <= 300),
    orgunit public.citext CHECK (char_length(orgunit) <= 120),
    orgrole public.citext CHECK (char_length(orgrole) <= 40),
    orgdepth integer,
    orgsince public.citext CHECK (char_length(orgsince) <= 40),
    positiontype public.citext CHECK (char_length(positiontype) <= 60),
    homebuilding public.citext CHECK (char_length(homebuilding) <= 60),
    homeroom public.citext CHECK (char_length(homeroom) <= 40),
    fieldstation public.citext CHECK (char_length(fieldstation) <= 120),
    roomtext public.citext CHECK (char_length(roomtext) <= 200),
    PRIMARY KEY (personid),
    UNIQUE (netid)
);
CREATE INDEX ref_people_ix_people_name ON equipment.ref_people (displayname);
CREATE TABLE equipment.ref_picklisttypes (
    listkey public.citext NOT NULL CHECK (char_length(listkey) <= 40),
    groupname public.citext NOT NULL CHECK (char_length(groupname) <= 60),
    title public.citext NOT NULL CHECK (char_length(title) <= 120),
    description public.citext CHECK (char_length(description) <= 400),
    usedon public.citext CHECK (char_length(usedon) <= 300),
    sortorder integer NOT NULL DEFAULT 100,
    PRIMARY KEY (listkey)
);
CREATE TABLE equipment.ref_picklists (
    picklistid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    listkey public.citext NOT NULL CHECK (char_length(listkey) <= 40),
    code public.citext NOT NULL CHECK (char_length(code) <= 60),
    label public.citext NOT NULL CHECK (char_length(label) <= 160),
    sortorder integer NOT NULL DEFAULT 100,
    isactive smallint NOT NULL DEFAULT 1,
    note public.citext CHECK (char_length(note) <= 300),
    isprotected smallint NOT NULL DEFAULT 0,
    updatedat timestamp(6),
    updatedbynetid public.citext CHECK (char_length(updatedbynetid) <= 64),
    PRIMARY KEY (picklistid),
    UNIQUE (listkey, code)
);
CREATE INDEX ref_picklists_ix_picklists_list ON equipment.ref_picklists (listkey, sortorder);
CREATE TABLE equipment.ref_rooms (
    roomcode public.citext NOT NULL CHECK (char_length(roomcode) <= 40),
    bldgnumber public.citext NOT NULL CHECK (char_length(bldgnumber) <= 10),
    floorcode public.citext NOT NULL CHECK (char_length(floorcode) <= 10),
    roomid public.citext NOT NULL CHECK (char_length(roomid) <= 40),
    roomkey public.citext NOT NULL CHECK (char_length(roomkey) <= 40),
    roomname public.citext CHECK (char_length(roomname) <= 200),
    surveycode public.citext CHECK (char_length(surveycode) <= 20),
    PRIMARY KEY (roomcode)
);
CREATE INDEX ref_rooms_ix_refrooms_lookup ON equipment.ref_rooms (bldgnumber, roomkey);
CREATE TABLE equipment.ref_statusflow (
    requesttype public.citext NOT NULL CHECK (char_length(requesttype) <= 20),
    statuscode public.citext NOT NULL CHECK (char_length(statuscode) <= 30),
    stageorder integer NOT NULL,
    label public.citext NOT NULL CHECK (char_length(label) <= 60),
    description public.citext CHECK (char_length(description) <= 300),
    ownerhint public.citext CHECK (char_length(ownerhint) <= 60),
    isterminal smallint NOT NULL DEFAULT 0,
    notifysubmitter smallint NOT NULL DEFAULT 1,
    isactive smallint NOT NULL DEFAULT 1,
    PRIMARY KEY (requesttype, statuscode)
);
CREATE TABLE equipment.ref_surveys (
    surveyid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    code public.citext NOT NULL CHECK (char_length(code) <= 10),
    name public.citext NOT NULL CHECK (char_length(name) <= 120),
    isactive smallint NOT NULL DEFAULT 1,
    directorname public.citext CHECK (char_length(directorname) <= 160),
    directoremail public.citext CHECK (char_length(directoremail) <= 200),
    proxyname public.citext CHECK (char_length(proxyname) <= 160),
    proxyemail public.citext CHECK (char_length(proxyemail) <= 200),
    notifydirector smallint NOT NULL DEFAULT 1,
    unitkind public.citext NOT NULL DEFAULT 'survey' CHECK (char_length(unitkind) <= 20),
    PRIMARY KEY (surveyid),
    UNIQUE (code)
);
CREATE TABLE equipment.rq_propertyupdates (
    propertyupdateid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    ticketnumber public.citext NOT NULL CHECK (char_length(ticketnumber) <= 30),
    requestedbynetid public.citext NOT NULL CHECK (char_length(requestedbynetid) <= 50),
    requestedbyuserid integer,
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    changekind public.citext NOT NULL CHECK (char_length(changekind) <= 20),
    inventoryid integer,
    propertytag public.citext CHECK (char_length(propertytag) <= 50),
    purchaseitemid integer,
    description public.citext CHECK (char_length(description) <= 300),
    model public.citext CHECK (char_length(model) <= 100),
    serialnumber public.citext CHECK (char_length(serialnumber) <= 100),
    equipclass public.citext CHECK (char_length(equipclass) <= 30),
    cost numeric(12,2),
    acquiredon public.citext CHECK (char_length(acquiredon) <= 40),
    fundingsource public.citext CHECK (char_length(fundingsource) <= 200),
    conditioncode public.citext CHECK (char_length(conditioncode) <= 30),
    tobldgnumber public.citext CHECK (char_length(tobldgnumber) <= 10),
    toroomid public.citext CHECK (char_length(toroomid) <= 30),
    toroomcode public.citext CHECK (char_length(toroomcode) <= 40),
    toperson public.citext CHECK (char_length(toperson) <= 150),
    topersonnetid public.citext CHECK (char_length(topersonnetid) <= 50),
    removalreason public.citext CHECK (char_length(removalreason) <= 30),
    removedon public.citext CHECK (char_length(removedon) <= 40),
    salvagevalue numeric(12,2),
    reason public.citext CHECK (char_length(reason) <= 1000),
    status public.citext NOT NULL DEFAULT 'submitted' CHECK (char_length(status) <= 20),
    decisionnote public.citext CHECK (char_length(decisionnote) <= 1000),
    appliedbynetid public.citext CHECK (char_length(appliedbynetid) <= 50),
    appliedat timestamp(6),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    updatedat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (propertyupdateid),
    UNIQUE (ticketnumber),
    CHECK (ChangeKind IN ('register', 'move', 'reassign', 'correct', 'remove')),
    CHECK (Status IN ('submitted', 'applied', 'declined'))
);
CREATE INDEX rq_propertyupdates_ix_propertyupdates_status ON equipment.rq_propertyupdates (status, createdat DESC);
CREATE INDEX rq_propertyupdates_ix_propertyupdates_inventory ON equipment.rq_propertyupdates (inventoryid);

-- ==== register incidents (PRI_FacilitiesIncidents) ====
CREATE SCHEMA incidents;
CREATE TABLE incidents.app_adminaccess (
    adminaccessid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    accessfunction public.citext NOT NULL DEFAULT 'facilities' CHECK (char_length(accessfunction) <= 30),
    note public.citext CHECK (char_length(note) <= 200),
    isactive smallint NOT NULL DEFAULT 1,
    grantedat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    grantedbynetid public.citext CHECK (char_length(grantedbynetid) <= 64),
    PRIMARY KEY (adminaccessid),
    UNIQUE (netid, surveycode, accessfunction),
    CHECK (AccessFunction IN ('director', 'proxy', 'facilities', 'safety', 'fleet', 'equipment', 'inventory', 'it', 'finance', 'deputy', 'executive'))
);
CREATE INDEX app_adminaccess_ix_adminaccess_netid ON incidents.app_adminaccess (netid, isactive);
CREATE TABLE incidents.app_attachments (
    attachmentid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    userid integer NOT NULL,
    storedname public.citext NOT NULL CHECK (char_length(storedname) <= 120),
    originalname public.citext NOT NULL CHECK (char_length(originalname) <= 260),
    mimetype public.citext NOT NULL CHECK (char_length(mimetype) <= 80),
    sizebytes bigint NOT NULL,
    exiflatitude numeric(9,6),
    exiflongitude numeric(9,6),
    capturedat timestamp(6),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    purpose public.citext NOT NULL DEFAULT 'photo' CHECK (char_length(purpose) <= 20),
    caption public.citext CHECK (char_length(caption) <= 300),
    requesttype public.citext CHECK (char_length(requesttype) <= 20),
    PRIMARY KEY (attachmentid),
    CHECK (Purpose IN ('photo', 'drawing', 'document', 'other'))
);
CREATE INDEX app_attachments_ix_attachments_request ON incidents.app_attachments (requestid);
CREATE TABLE incidents.app_auditlog (
    auditid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    userid integer,
    action public.citext NOT NULL CHECK (char_length(action) <= 60),
    targettype public.citext CHECK (char_length(targettype) <= 40),
    targetid public.citext CHECK (char_length(targetid) <= 40),
    detail public.citext,
    ipaddress public.citext CHECK (char_length(ipaddress) <= 45),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (auditid)
);
CREATE TABLE incidents.app_digestpreferences (
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    frequency public.citext NOT NULL DEFAULT 'weekly' CHECK (char_length(frequency) <= 10),
    sendday integer NOT NULL DEFAULT 1,
    sendhour integer NOT NULL DEFAULT 7,
    includemine smallint NOT NULL DEFAULT 1,
    token public.citext NOT NULL CHECK (char_length(token) <= 64),
    lastsentat timestamp(6),
    lastitemcount integer,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (netid),
    UNIQUE (token),
    CHECK (Frequency IN ('off', 'daily', 'weekly'))
);
CREATE TABLE incidents.app_notes (
    noteid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    userid integer NOT NULL,
    body public.citext NOT NULL,
    isinternal smallint NOT NULL DEFAULT 0,
    importbatchid integer,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (noteid)
);
CREATE INDEX app_notes_ix_notes_request ON incidents.app_notes (requestid);
CREATE TABLE incidents.app_notifications (
    notificationid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer,
    ticketnumber public.citext CHECK (char_length(ticketnumber) <= 24),
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 40),
    recipients public.citext NOT NULL,
    subject public.citext NOT NULL CHECK (char_length(subject) <= 300),
    body public.citext NOT NULL,
    status public.citext NOT NULL DEFAULT 'logged' CHECK (char_length(status) <= 20),
    errortext public.citext CHECK (char_length(errortext) <= 600),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    sentat timestamp(6),
    PRIMARY KEY (notificationid),
    CHECK (Status IN ('logged', 'sent', 'failed'))
);
CREATE INDEX app_notifications_ix_notifications_created ON incidents.app_notifications (createdat DESC);
CREATE TABLE incidents.app_notifyrules (
    ruleid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 40),
    matchtype public.citext NOT NULL DEFAULT 'always' CHECK (char_length(matchtype) <= 20),
    matchvalue public.citext CHECK (char_length(matchvalue) <= 120),
    email public.citext NOT NULL CHECK (char_length(email) <= 200),
    displayname public.citext CHECK (char_length(displayname) <= 160),
    note public.citext CHECK (char_length(note) <= 300),
    isactive smallint NOT NULL DEFAULT 1,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    createdbynetid public.citext CHECK (char_length(createdbynetid) <= 64),
    PRIMARY KEY (ruleid),
    CHECK (MatchType IN ('always', 'survey', 'work_type', 'owner', 'request_kind', 'severity_min', 'building', 'life_safety', 'specimen_risk'))
);
CREATE INDEX app_notifyrules_ix_notifyrules_event ON incidents.app_notifyrules (eventcode, isactive);
CREATE TABLE incidents.app_settings (
    settingkey public.citext NOT NULL CHECK (char_length(settingkey) <= 60),
    settingvalue public.citext NOT NULL CHECK (char_length(settingvalue) <= 400),
    valuetype public.citext NOT NULL DEFAULT 'number' CHECK (char_length(valuetype) <= 20),
    label public.citext NOT NULL CHECK (char_length(label) <= 160),
    helptext public.citext CHECK (char_length(helptext) <= 400),
    sortorder integer NOT NULL DEFAULT 0,
    PRIMARY KEY (settingkey)
);
CREATE TABLE incidents.app_statushistory (
    historyid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    fromstatus public.citext CHECK (char_length(fromstatus) <= 20),
    tostatus public.citext NOT NULL CHECK (char_length(tostatus) <= 20),
    userid integer,
    comment public.citext CHECK (char_length(comment) <= 600),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (historyid)
);
CREATE INDEX app_statushistory_ix_history_request ON incidents.app_statushistory (requestid);
CREATE TABLE incidents.app_users (
    userid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    displayname public.citext NOT NULL CHECK (char_length(displayname) <= 160),
    email public.citext NOT NULL CHECK (char_length(email) <= 200),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    unit public.citext CHECK (char_length(unit) <= 120),
    phone public.citext CHECK (char_length(phone) <= 40),
    role public.citext NOT NULL DEFAULT 'staff' CHECK (char_length(role) <= 20),
    isprovisional smallint NOT NULL DEFAULT 0,
    isactive smallint NOT NULL DEFAULT 1,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    lastloginat timestamp(6),
    PRIMARY KEY (userid),
    UNIQUE (netid),
    CHECK (Role IN ('staff', 'coordinator', 'approver', 'admin'))
);
CREATE TABLE incidents.ref_buildingaliases (
