CREATE INDEX ref_buildings_ix_buildings_sort ON incidents.ref_buildings (sortkey);
CREATE TABLE incidents.ref_owners (
    ownerid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    code public.citext NOT NULL CHECK (char_length(code) <= 20),
