    isoffcampus smallint NOT NULL DEFAULT 0,
    fleetnumber public.citext CHECK (char_length(fleetnumber) <= 30),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    reportedbynetid public.citext NOT NULL CHECK (char_length(reportedbynetid) <= 50),
    reportedbyname public.citext CHECK (char_length(reportedbyname) <= 150),
