);
CREATE INDEX rq_incidents_ix_incidents_when ON incidents.rq_incidents (occurredat DESC);
CREATE INDEX rq_incidents_ix_incidents_where ON incidents.rq_incidents (roomcode);
CREATE TABLE incidents.rq_incidentactions (
