    frequency public.citext NOT NULL DEFAULT 'weekly' CHECK (char_length(frequency) <= 10),
    sendday integer NOT NULL DEFAULT 1,
    sendhour integer NOT NULL DEFAULT 7,
    includemine smallint NOT NULL DEFAULT 1,
    token public.citext NOT NULL CHECK (char_length(token) <= 64),
    lastsentat timestamp(6),
    lastitemcount integer,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (netid),
    UNIQUE (token),
    CHECK (Frequency IN ('off', 'daily', 'weekly'))
);
CREATE TABLE plans.app_notes (
    noteid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    userid integer NOT NULL,
    body public.citext NOT NULL,
    isinternal smallint NOT NULL DEFAULT 0,
    importbatchid integer,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (noteid)
);
CREATE INDEX app_notes_ix_notes_request ON plans.app_notes (requestid);
CREATE TABLE plans.app_notifications (
    notificationid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer,
    ticketnumber public.citext CHECK (char_length(ticketnumber) <= 24),
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 40),
    recipients public.citext NOT NULL,
    subject public.citext NOT NULL CHECK (char_length(subject) <= 300),
    body public.citext NOT NULL,
    status public.citext NOT NULL DEFAULT 'logged' CHECK (char_length(status) <= 20),
    errortext public.citext CHECK (char_length(errortext) <= 600),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    sentat timestamp(6),
    PRIMARY KEY (notificationid),
    CHECK (Status IN ('logged', 'sent', 'failed'))
);
CREATE INDEX app_notifications_ix_notifications_created ON plans.app_notifications (createdat DESC);
CREATE TABLE plans.app_notifyrules (
    ruleid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    eventcode public.citext NOT NULL CHECK (char_length(eventcode) <= 40),
    matchtype public.citext NOT NULL DEFAULT 'always' CHECK (char_length(matchtype) <= 20),
    matchvalue public.citext CHECK (char_length(matchvalue) <= 120),
    email public.citext NOT NULL CHECK (char_length(email) <= 200),
    displayname public.citext CHECK (char_length(displayname) <= 160),
    note public.citext CHECK (char_length(note) <= 300),
    isactive smallint NOT NULL DEFAULT 1,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    createdbynetid public.citext CHECK (char_length(createdbynetid) <= 64),
    PRIMARY KEY (ruleid),
    CHECK (MatchType IN ('always', 'survey', 'work_type', 'owner', 'request_kind', 'severity_min', 'building', 'life_safety', 'specimen_risk'))
);
CREATE INDEX app_notifyrules_ix_notifyrules_event ON plans.app_notifyrules (eventcode, isactive);
CREATE TABLE plans.app_settings (
    settingkey public.citext NOT NULL CHECK (char_length(settingkey) <= 60),
    settingvalue public.citext NOT NULL CHECK (char_length(settingvalue) <= 400),
    valuetype public.citext NOT NULL DEFAULT 'number' CHECK (char_length(valuetype) <= 20),
    label public.citext NOT NULL CHECK (char_length(label) <= 160),
    helptext public.citext CHECK (char_length(helptext) <= 400),
    sortorder integer NOT NULL DEFAULT 0,
    PRIMARY KEY (settingkey)
);
CREATE TABLE plans.app_statushistory (
    historyid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requestid integer NOT NULL,
    fromstatus public.citext CHECK (char_length(fromstatus) <= 20),
    tostatus public.citext NOT NULL CHECK (char_length(tostatus) <= 20),
    userid integer,
    comment public.citext CHECK (char_length(comment) <= 600),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (historyid)
);
CREATE INDEX app_statushistory_ix_history_request ON plans.app_statushistory (requestid);
CREATE TABLE plans.app_users (
    userid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    displayname public.citext NOT NULL CHECK (char_length(displayname) <= 160),
    email public.citext NOT NULL CHECK (char_length(email) <= 200),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    unit public.citext CHECK (char_length(unit) <= 120),
    phone public.citext CHECK (char_length(phone) <= 40),
    role public.citext NOT NULL DEFAULT 'staff' CHECK (char_length(role) <= 20),
    isprovisional smallint NOT NULL DEFAULT 0,
    isactive smallint NOT NULL DEFAULT 1,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    lastloginat timestamp(6),
    PRIMARY KEY (userid),
    UNIQUE (netid),
    CHECK (Role IN ('staff', 'coordinator', 'approver', 'admin'))
);
CREATE TABLE plans.ref_buildingaliases (
    aliasid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    buildingid integer NOT NULL,
    aliastext public.citext NOT NULL CHECK (char_length(aliastext) <= 200),
    aliasnorm public.citext NOT NULL CHECK (char_length(aliasnorm) <= 200),
    source public.citext NOT NULL DEFAULT 'seed' CHECK (char_length(source) <= 40),
    PRIMARY KEY (aliasid),
    CHECK (Source IN ('seed', 'legacy', 'fs', 'gis', 'manual'))
);
CREATE INDEX ref_buildingaliases_ix_aliases_norm ON plans.ref_buildingaliases (aliasnorm);
CREATE TABLE plans.ref_buildings (
    buildingid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    bldgnumber public.citext NOT NULL CHECK (char_length(bldgnumber) <= 10),
    sortkey public.citext NOT NULL CHECK (char_length(sortkey) <= 20),
    shortcode public.citext CHECK (char_length(shortcode) <= 20),
    name public.citext NOT NULL CHECK (char_length(name) <= 200),
    addressline public.citext CHECK (char_length(addressline) <= 200),
    city public.citext CHECK (char_length(city) <= 80),
    isoncampus smallint NOT NULL DEFAULT 1,
    isremote smallint NOT NULL DEFAULT 0,
    criticality integer NOT NULL DEFAULT 0,
    latitude numeric(9,6),
    longitude numeric(9,6),
    gisfeatureid public.citext CHECK (char_length(gisfeatureid) <= 64),
    requiresfreetext smallint NOT NULL DEFAULT 0,
    isactive smallint NOT NULL DEFAULT 1,
    name2 public.citext CHECK (char_length(name2) <= 300),
    addressname public.citext CHECK (char_length(addressname) <= 200),
    statecode public.citext CHECK (char_length(statecode) <= 10),
    postalcode public.citext CHECK (char_length(postalcode) <= 20),
    locationclass public.citext CHECK (char_length(locationclass) <= 30),
    buildingtype public.citext CHECK (char_length(buildingtype) <= 60),
    ownership public.citext CHECK (char_length(ownership) <= 40),
    condition public.citext CHECK (char_length(condition) <= 30),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    pripriority integer,
    PRIMARY KEY (buildingid),
    UNIQUE (bldgnumber)
);
CREATE INDEX ref_buildings_ix_buildings_sort ON plans.ref_buildings (sortkey);
CREATE TABLE plans.ref_owners (
    ownerid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    code public.citext NOT NULL CHECK (char_length(code) <= 20),
    name public.citext NOT NULL CHECK (char_length(name) <= 120),
    handoffemail public.citext CHECK (char_length(handoffemail) <= 200),
    handoffurl public.citext CHECK (char_length(handoffurl) <= 400),
    showsonboard smallint NOT NULL DEFAULT 1,
    PRIMARY KEY (ownerid),
    UNIQUE (code)
);
CREATE TABLE plans.ref_people (
    personid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    netid public.citext NOT NULL CHECK (char_length(netid) <= 64),
    displayname public.citext NOT NULL CHECK (char_length(displayname) <= 160),
    email public.citext CHECK (char_length(email) <= 200),
    uin public.citext CHECK (char_length(uin) <= 40),
    surveycode public.citext CHECK (char_length(surveycode) <= 20),
    org public.citext CHECK (char_length(org) <= 200),
    position public.citext CHECK (char_length(position) <= 160),
    isactive smallint NOT NULL DEFAULT 1,
    sourcelabel public.citext CHECK (char_length(sourcelabel) <= 60),
    updatedat timestamp(6),
    firstname public.citext CHECK (char_length(firstname) <= 80),
    lastname public.citext CHECK (char_length(lastname) <= 80),
    orgpath public.citext CHECK (char_length(orgpath) <= 300),
    orgunit public.citext CHECK (char_length(orgunit) <= 120),
    orgrole public.citext CHECK (char_length(orgrole) <= 40),
    orgdepth integer,
    orgsince public.citext CHECK (char_length(orgsince) <= 40),
    positiontype public.citext CHECK (char_length(positiontype) <= 60),
    homebuilding public.citext CHECK (char_length(homebuilding) <= 60),
    homeroom public.citext CHECK (char_length(homeroom) <= 40),
    fieldstation public.citext CHECK (char_length(fieldstation) <= 120),
    roomtext public.citext CHECK (char_length(roomtext) <= 200),
    PRIMARY KEY (personid),
    UNIQUE (netid)
);
CREATE INDEX ref_people_ix_people_name ON plans.ref_people (displayname);
CREATE TABLE plans.ref_picklisttypes (
    listkey public.citext NOT NULL CHECK (char_length(listkey) <= 40),
    groupname public.citext NOT NULL CHECK (char_length(groupname) <= 60),
    title public.citext NOT NULL CHECK (char_length(title) <= 120),
    description public.citext CHECK (char_length(description) <= 400),
    usedon public.citext CHECK (char_length(usedon) <= 300),
    sortorder integer NOT NULL DEFAULT 100,
    PRIMARY KEY (listkey)
);
CREATE TABLE plans.ref_picklists (
    picklistid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    listkey public.citext NOT NULL CHECK (char_length(listkey) <= 40),
    code public.citext NOT NULL CHECK (char_length(code) <= 60),
    label public.citext NOT NULL CHECK (char_length(label) <= 160),
    sortorder integer NOT NULL DEFAULT 100,
    isactive smallint NOT NULL DEFAULT 1,
    note public.citext CHECK (char_length(note) <= 300),
    isprotected smallint NOT NULL DEFAULT 0,
    updatedat timestamp(6),
    updatedbynetid public.citext CHECK (char_length(updatedbynetid) <= 64),
    PRIMARY KEY (picklistid),
    UNIQUE (listkey, code)
);
CREATE INDEX ref_picklists_ix_picklists_list ON plans.ref_picklists (listkey, sortorder);
CREATE TABLE plans.ref_plantypes (
    plantypecode public.citext NOT NULL CHECK (char_length(plantypecode) <= 30),
    title public.citext NOT NULL CHECK (char_length(title) <= 150),
    reviewmonths integer NOT NULL DEFAULT 12,
    appliesto public.citext CHECK (char_length(appliesto) <= 200),
    description public.citext CHECK (char_length(description) <= 1000),
    sortorder integer NOT NULL DEFAULT 100,
    isactive smallint NOT NULL DEFAULT 1,
    PRIMARY KEY (plantypecode)
);
CREATE TABLE plans.ref_rooms (
    roomcode public.citext NOT NULL CHECK (char_length(roomcode) <= 40),
    bldgnumber public.citext NOT NULL CHECK (char_length(bldgnumber) <= 10),
    floorcode public.citext NOT NULL CHECK (char_length(floorcode) <= 10),
    roomid public.citext NOT NULL CHECK (char_length(roomid) <= 40),
    roomkey public.citext NOT NULL CHECK (char_length(roomkey) <= 40),
    roomname public.citext CHECK (char_length(roomname) <= 200),
    surveycode public.citext CHECK (char_length(surveycode) <= 20),
    PRIMARY KEY (roomcode)
);
CREATE INDEX ref_rooms_ix_refrooms_lookup ON plans.ref_rooms (bldgnumber, roomkey);
CREATE TABLE plans.ref_statusflow (
    requesttype public.citext NOT NULL CHECK (char_length(requesttype) <= 20),
    statuscode public.citext NOT NULL CHECK (char_length(statuscode) <= 30),
    stageorder integer NOT NULL,
    label public.citext NOT NULL CHECK (char_length(label) <= 60),
    description public.citext CHECK (char_length(description) <= 300),
    ownerhint public.citext CHECK (char_length(ownerhint) <= 60),
    isterminal smallint NOT NULL DEFAULT 0,
    notifysubmitter smallint NOT NULL DEFAULT 1,
    isactive smallint NOT NULL DEFAULT 1,
    PRIMARY KEY (requesttype, statuscode)
);
CREATE TABLE plans.ref_surveys (
    surveyid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    code public.citext NOT NULL CHECK (char_length(code) <= 10),
    name public.citext NOT NULL CHECK (char_length(name) <= 120),
    isactive smallint NOT NULL DEFAULT 1,
    directorname public.citext CHECK (char_length(directorname) <= 160),
    directoremail public.citext CHECK (char_length(directoremail) <= 200),
    proxyname public.citext CHECK (char_length(proxyname) <= 160),
    proxyemail public.citext CHECK (char_length(proxyemail) <= 200),
    notifydirector smallint NOT NULL DEFAULT 1,
    unitkind public.citext NOT NULL DEFAULT 'survey' CHECK (char_length(unitkind) <= 20),
    PRIMARY KEY (surveyid),
    UNIQUE (code)
);
CREATE TABLE plans.rq_safetyplans (
    safetyplanid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    ticketnumber public.citext NOT NULL CHECK (char_length(ticketnumber) <= 30),
    plantypecode public.citext NOT NULL CHECK (char_length(plantypecode) <= 30),
    title public.citext NOT NULL CHECK (char_length(title) <= 300),
    reference public.citext CHECK (char_length(reference) <= 60),
    version public.citext CHECK (char_length(version) <= 30),
    ownername public.citext NOT NULL CHECK (char_length(ownername) <= 150),
    ownernetid public.citext CHECK (char_length(ownernetid) <= 50),
    surveycode public.citext CHECK (char_length(surveycode) <= 10),
    unitname public.citext CHECK (char_length(unitname) <= 150),
    effectiveon date,
    reviewdueon date,
    lastreviewedon date,
    summary public.citext,
    status public.citext NOT NULL DEFAULT 'current' CHECK (char_length(status) <= 20),
    filedbynetid public.citext NOT NULL CHECK (char_length(filedbynetid) <= 50),
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    updatedat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (safetyplanid),
    UNIQUE (ticketnumber),
    CHECK (Status IN ('draft', 'current', 'due', 'withdrawn'))
);
CREATE INDEX rq_safetyplans_ix_safetyplans_due ON plans.rq_safetyplans (reviewdueon);
CREATE TABLE plans.rq_planreviews (
    planreviewid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    safetyplanid integer NOT NULL,
    reviewedon date NOT NULL,
    reviewedbynetid public.citext CHECK (char_length(reviewedbynetid) <= 50),
    reviewedbyname public.citext CHECK (char_length(reviewedbyname) <= 150),
    outcome public.citext NOT NULL DEFAULT 'unchanged' CHECK (char_length(outcome) <= 30),
    note public.citext CHECK (char_length(note) <= 1000),
    nextdueon date,
    createdat timestamp(6) NOT NULL DEFAULT CAST(statement_timestamp() AS timestamp(6)),
    PRIMARY KEY (planreviewid)
);
CREATE TABLE plans.rq_planrooms (
    planroomid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    safetyplanid integer NOT NULL,
    roomcode public.citext CHECK (char_length(roomcode) <= 40),
    bldgnumber public.citext CHECK (char_length(bldgnumber) <= 10),
    coverswholebuilding smallint NOT NULL DEFAULT 0,
    note public.citext CHECK (char_length(note) <= 300),
    PRIMARY KEY (planroomid)
);
CREATE INDEX rq_planrooms_ix_planrooms_room ON plans.rq_planrooms (roomcode);

